"""A word-initial 'u' detector, strongest for Russian у/У.

Short u-starting fragments and the letter just after a separate у get
smaller responses. Ukrainian і/ї/є/ґ and Central-European Slavic diacritics
in recent text adjust the response to Ukrainian в and Latin u/ú.
There are small responses to the diphthong ou and Japanese もう.
The byte stream is decoded across token boundaries. State remembers only
250 recent characters, the preceding token, and unfinished UTF-8 bytes.
"""
import re
import codecs

READS = ()
UKRAINIAN = re.compile('[іїєґ]', re.I)
CENTRAL_SLAVIC = re.compile('[ěščřžůďťňľĺŕôąćęłńśźż]', re.I)
RUSSIAN_VOWELS = set('аеёиоуыэюя')
# The glide й is not included in the following consonant rule.
RUSSIAN_CONSONANTS = set('бвгджзклмнпрстфхцчшщ')
NASALS_AND_LIQUIDS = set('лмнр')


def predict(token, previous, recent):
    word = token.strip().lower()
    if not word:
        return 0.0
    spaced = token[0].isspace()
    boundary = spaced or not recent or not recent[-1].isalpha()
    ukrainian = bool(UKRAINIAN.search(recent))
    value = 0.0
    if word == 'у':
        if not recent:
            value = 2.5
        elif spaced:
            value = 8.9 if token.strip().isupper() else 11.6
        elif boundary:
            value = 10.7
        elif recent[-1].lower() in RUSSIAN_VOWELS:
            value = 6.5
        else:
            preceding_word = re.search(r'\w+$', recent)
            length = len(preceding_word[0]) if preceding_word else 0
            value = 3.0 if length == 1 else 1.2 if length <= 3 else 0.35
            if token.strip().isupper():
                value = 3.2
        if ukrainian and boundary:
            value = 6.0
    elif word.startswith('у') and len(word) == 2:
        value = 2.2 if boundary else 0.6
    elif word.startswith('в') and len(word) <= 2:
        if ukrainian and boundary:
            value = (1.9 if token.strip().isupper() else 3.1)
        elif word == 'в' and spaced:
            value = -0.25
    elif word[0] in 'uúů' and len(word) <= 2:
        if CENTRAL_SLAVIC.search(recent):
            value = 0.7
            if boundary:
                value = 5.0 if len(word) == 1 or word == 'us' else 3.0
        elif word in ('u', 'ú'):
            value = 0.15 if word == 'u' else 1.0
    elif word == 'ou' and CENTRAL_SLAVIC.search(recent):
        value = 0.9
    elif word == 'もう':
        value = 2.3
    if previous.strip().lower() == 'у' and not spaced and word.isalpha():
        if word in RUSSIAN_CONSONANTS:
            value += 5.0 if word in NASALS_AND_LIQUIDS else 2.5
        elif len(word) <= 3:
            value += 0.3
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        recent, previous, pending = '', '', b''
    else:
        _, recent, previous, pending = carry
    raw = pending + prefix.token_bytes[-1]
    token, used = codecs.utf_8_decode(raw, 'replace', False)
    pending = raw[used:]
    value = predict(token, previous, recent)
    return (document, (recent + token)[-250:], token, pending), value

"""A token-sensitive spelling detector for pod / под, not their meanings.

A fragment completed across a token boundary gets a larger pulse. Longer
merged pod/под tokens get weaker pulses. Split під and пад also respond.
Split Greek ποδ / ποι show a similar contrast. Pain/poison spellings are negative;
za/за and repeated middle dots get small corrections.
The short text tail is cleared at document boundaries.
"""
READS = ()


def predict(text, before):
    s, p = text.casefold(), before.casefold()
    word = s.strip()
    if len(word) > 1 and set(word) == {'·'}:
        return -1.01
    if word in ('за', 'za') and s != word:
        return 1.08

    if word.lstrip('._') == 'poi':
        return -4.8

    if s and not s[0].isspace():
        if p.endswith('π') and s.startswith('ο'):
            return 1.6
        if p.endswith('πο') and s.startswith('δ'):
            return 5.2
        if p.endswith('πο') and s.startswith(('ι', 'ί')):
            return -4.2
        # Complete the spelling using the immediately preceding letters.
        if (p.endswith('п') and s.startswith('од')) or (
            p.endswith('по') and s.startswith('д')
        ):
            return 18.3
        if p.endswith('пі') and s.startswith('д'):
            return 17.5
        if p.endswith('п') and s.startswith('ад'):
            return 4.73
        if (p.endswith('p') and s.startswith('od')) or (
            p.endswith('po') and s.startswith('d')
        ):
            completion = 'o' + s if p.endswith('po') else s
            return 12.44 if completion == 'od' else (
                9.95 if completion == 'ods' else 5.31
            )
        if s == 's' and p.endswith('pod'):
            return 8.11
        if p.endswith('p') and s in ('ain', 'ains'):
            return -4.5
        if (p.endswith('p') and s.startswith('oi')) or (
            p.endswith('po') and s.startswith('i')
        ):
            return -4.73

    if word.endswith('под'):
        return 12.6
    if word.startswith('под'):
        return 2.86
    if word.endswith('pod'):
        return 7.84
    if word.endswith('pods'):
        return 6.15
    if word.startswith('pod'):
        return 0.58
    if word in ('pain', 'pains'):
        return -1.81
    if word.startswith('pain') and not word.startswith('paint'):
        return -0.18
    if word == 'poison':
        return -4.51
    if word.startswith('poison'):
        return -2.19
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    return (doc, (before + text)[-20:]), predict(text, before)

"""A small approximation of the component's negative response to international
word stems in non-English prose. A stem is the part left after removing an
English derivational ending (administr-ation, econom-y, etc.). Recent completed
words estimate whether the surrounding language is English. Only the current
word-so-far is tested, not its later inflections. Initial-token biases and two
literal separator patterns are separate minor cases. Most responses, including
other lexical and non-Latin effects, are not explained by these rules.
"""
import re
from functools import lru_cache
from wordfreq import top_n_list, zipf_frequency

READS = ()
LANGUAGES = 'en fr es de it pt ro lv sv fi da nb nl cs pl tr'.split()
# Nominalizations, adjectives, verbs, and final silent-e / -y forms.
ENDINGS = (
    'ation ition ution tion sion ment ance ence ity ism'.split(),
    'ic ical al ial ual ive ative ous ary ory ant ent'.split(),
    'ate ize ise ify'.split(),
    ('e', 'y'),
)
STEMS = [set() for _ in ENDINGS]
for word in top_n_list('en', 40000):
    if (not word.isascii() or not word.isalpha() or len(word) < 6
            or zipf_frequency(word, 'en') < 2.8):
        continue
    for stems, endings in zip(STEMS, ENDINGS):
        for ending in endings:
            if word.endswith(ending) and len(word) - len(ending) >= 4:
                stem = word[:-len(ending)]
                stems.update((stem, stem.replace('ph', 'f').replace('th', 't'),
                              stem.replace('c', 'k')))


@lru_cache(maxsize=50000)
def evidence(word):
    return tuple(max(0.0, zipf_frequency(word, lang) - 2.0)
                 for lang in LANGUAGES)


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        word, scores, age, previous = '', (0.0,) * len(LANGUAGES), 0, ''
    else:
        _, word, scores, age, previous = carry
    for part in re.findall(r'[^\W\d_]+|[\W\d_]+', token):
        if part.isalpha():
            word += part.lower()
        else:
            if len(word) > 1:
                scores = tuple(0.8 * a + b
                               for a, b in zip(scores, evidence(word)))
            word = ''
    word = word[-32:]
    foreign = max(0.0, min(1.0, (max(scores[1:]) - scores[0] - 0.5) / 3.0))
    penalty = sum(weight for stems, weight in zip(STEMS, (0.08, 0.08, 0.055, 0.06))
                  if word in stems)
    value = -foreign * penalty
    piece = token.strip()
    if age == 0:
        if zipf_frequency(piece.lower(), 'en') > 7.0:
            value = 0.11
        else:
            value = -0.14 if piece[:1].isupper() else -0.026
    if token and set(token) == {'·'} and len(token) >= 2:
        value = -0.68
    if age == 1 and previous == 'Home' and piece == '»':
        value = 1.15
    return (doc, word, scores, age + 1, token), value

"""Mostly a negative response to a standalone space (often before a number).

Indentation, numeric runs, and space-heavy formatting weaken the response;
dates strengthen it. Small negative responses also mark unspaced delimiters.
There is a separate, very large response to the colon in document-initial
'Title:'. Initial tabs and repeated middle-dot filler are also recognized.
Only a bounded recent-token window is kept, reset per document.
"""
import re

READS = ()
MONTHS = {
    'january', 'february', 'march', 'april', 'may', 'june',
    'july', 'august', 'september', 'october', 'november', 'december',
    'jan', 'feb', 'mar', 'apr', 'jun', 'jul', 'aug', 'sep', 'sept',
    'oct', 'nov', 'dec',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        n, recent = 0, ()
    else:
        _, n, recent = carry
    previous = recent[-1] if recent else ''
    value = -0.006
    if s == ' ':
        text = ''.join(recent)
        value = -1.76
        if previous == ' ':
            value += 0.20
        elif previous == '  ':
            value += 0.45
        elif '\n' in previous:
            value += 0.30
        elif previous.isspace():
            value += 0.35
        elif previous[-1:].isdigit():
            value += 0.60
        elif previous.endswith(','):
            value -= 0.15
        elif previous.strip() and all(c in '=+-*/<>%&|!~^'
                                     for c in previous.strip()):
            value += 0.10
        value += 0.06 * min(4, text.count('  '))
        value += 1.05 * recent.count(' ') / max(1, len(recent))
        words = re.findall(r'\w+', text.lower())
        if any(word in MONTHS for word in words[-3:]):
            value -= 0.65
        if n == 0:
            value = 1.146
    elif s == '_':
        value = -0.78
    elif s == '(':
        value = -0.37
    elif s in ('[', '{'):
        value = -0.14
    elif s == ',' and previous[-1:].isdigit():
        value = -0.20
    elif s == '··' and previous == s:
        value = -2.05
    if n == 0 and s == '\t':
        value = -3.20
    if n == 0 and s == 'Title':
        value = 1.48
    elif n == 1 and previous == 'Title' and s == ':':
        value = -59.01
    return (doc, n + 1, (recent + (s,))[-16:]), value

"""Phrase-boundary pulses, strongest on closing quotes and ! or ?.

A run of several words is evidence for prose rather than code. This makes
closing quotes, semicolons, colons and unpunctuated line endings more negative.
Ordinary letters, numbers, commas and full stops are mostly quiet.
The line and phrase histories are capped at 128 characters and reset when
the document label changes; the first token has its own small adjustment.
"""
import re
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, line, phrase, quote_age = '', '', '', 0
    else:
        _, previous, line, phrase, quote_age = carry
    s = prefix.token_strings[-1]
    letters = any(c.isalpha() for c in s)
    leading_space = s.startswith(' ')
    words = len(phrase.split())
    line_words = len(line.split())
    lower = previous.strip().islower()
    after_word = previous[-1:].isalpha()
    last_word = re.search(r'[^\W\d_]+$', phrase)
    word_length = len(last_word[0]) if last_word else 0
    punctuation = any(unicodedata.category(c)[0] in 'PS' for c in s)
    value = 0.0

    if '?' in s or '？' in s:
        if not after_word:
            value = -0.38
        else:
            value = -0.60 if any(c.isspace() for c in s) else -0.83
    elif '!' in s or '！' in s:
        value = (-0.16 if leading_space
                 else -0.49 if word_length < 3 else -1.0)
    elif '"' in s:
        if leading_space:
            value = -0.03
        elif words >= 3:
            value = (-0.58 if line_words < 6
                     else -1.53 if len(s) < 3 else -0.98)
        elif line_words >= 6 and '(' not in s:
            value = -0.74 if quote_age >= 12 else -0.32
        else:
            value = -0.13
    elif any(c in s for c in '”’」』»') and (not letters or '’' not in s):
        value = -0.54 if len(phrase) < 12 else -1.11
    elif letters:
        if not previous:
            value = 0.21
        elif '\\' in s and previous.startswith(' '):
            value = -0.59
    elif '|' in s:
        value = -0.35
    elif "'" in s and not leading_space:
        value = -0.31 if not lower else -0.11
    elif '`' in s:
        value = -0.46 if lower and words >= 3 else -0.16
    elif lower and words >= 3:
        if ';' in s:
            value = -0.52 if line_words >= 6 else -0.03
        elif '\n' in s:
            value = -0.26 if not punctuation else -0.06
        elif s.strip() == ':':
            value = -0.24
        elif len(s) > 1:
            value = -0.17 if word_length >= 4 else -0.04

    line = (line + s).split('\n')[-1][-128:]
    phrase = re.split(r'[.,;:!?\n"“”‘’]', phrase + s)[-1][-128:]
    quote_age = (0 if any(c in s for c in '"“”')
                 else min(128, quote_age + len(s)))
    return (doc, s, line, phrase, quote_age), float(value)

"""Detect printing / standard-I/O code, not general-purpose logging.

Printing calls, console output, I/O headers and typed main declarations get
negative values. Statement starts (including indented, commented, numbered,
and escaped source lines) distinguish Python print calls from prose uses.
The latter get a small positive value. Code inside escaped strings has a
weaker print response than ordinary source lines. Other tokens are near zero.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    name = token.strip()
    line = re.split(r'\n|\\n', history)[-1].replace('\\t', '\t')
    statement = re.fullmatch(r'\s*(?:\d+)?[\s#|/]*', line) is not None
    spaced = token[:1].isspace()
    tabbed = token.startswith('\t')
    previous = history.rstrip()
    value = 0.0

    if name.lstrip('#') == 'print':
        if statement:
            escaped = history.rfind('\\n') > history.rfind('\n')
            if tabbed:
                value = -10.0
            elif spaced:
                value = -8.2 if escaped else -9.7
            else:
                value = -4.0 if escaped else -8.2
        elif previous.endswith('`') or re.search(r'[:;{]\s*$', history):
            value = -4.0
        else:
            value = 1.0
    elif name == 'printf':
        value = (-6.8 if tabbed or not spaced else -8.2) if statement else -2.5
    elif name == 'println':
        value = (-8.4 if statement else -6.5) if spaced else -2.8
    elif name == 'echo':
        value = (-2.6 if tabbed else -5.0) if statement else -1.0
    elif name == 'cout':
        value = 0.0 if history[-1:].isalpha() else -8.4
    elif name == '<<' and previous.endswith('cout'):
        value = -5.5 if spaced else -3.8
    elif name == 'console':
        value = (-4.0 if spaced else -2.8) if statement else -2.5
    elif name == '.log' and previous.endswith('console'):
        value = -9.9
    elif name == 'Console':
        value = -7.0 if statement else (-3.0 if previous.endswith('=') else 0.0)
    elif name == '.WriteLine':
        value = -8.1
    elif name == '.Write' and previous.endswith('Console'):
        value = -5.5
    elif name == '.out' and previous.endswith('System'):
        value = -10.8
    elif name == '.println' and previous.endswith('System.out'):
        value = -6.5
    elif name in {'.printf', '.print'} and previous.endswith('System.out'):
        value = -3.0
    elif name in {'.Printf', '.Println'} and previous.endswith('fmt'):
        value = -6.5 if name == '.Printf' else -8.0
    elif name.strip('"<') == 'fmt':
        if previous.endswith('"') or name.startswith('"'):
            value = -8.0
        else:
            value = -3.5 if spaced and not statement else -5.5
    elif name == '.printStackTrace':
        value = -2.5
    elif name == 'writeln':
        value = -5.4
    elif name.lstrip('<') in {'stdio', 'iostream'}:
        value = -10.6 if name.endswith('stdio') else -9.2
    elif name == '.h' and previous.endswith('stdio'):
        value = -3.4
    elif name in {'main', 'Main'} and re.search(r'\b(?:int|void)\s*$', history):
        value = -9.2
    elif name == 'main' and re.search(r'\bfunc\s*$', history):
        value = -6.0
    elif name == 'main' and previous.endswith('__'):
        value = -2.2
    elif name == 'std' and previous.endswith('namespace'):
        value = -6.0
    elif name == 'System' and statement and spaced:
        value = -2.2 if tabbed else -1.5
    elif name == 'Log' and statement and spaced:
        value = -3.3

    return (doc, (history + token)[-300:]), value

"""Approximate a standard-library scope-qualifier detector.

A separate '::' after the identifier std is the main response. It is
stronger at the start of a statement and weaker after Rust modifiers.
Other lowercase namespace qualifiers have a small positive response;
mixed/uppercase type qualifiers a small negative one. A document-opening
'Title:' label is a second strong trigger. Ordinary opening words receive
a small negative offset; everything else is approximated by zero.
"""
import re

READS = ()
IDENTIFIER = re.compile(r'([A-Za-z_][A-Za-z_0-9]*)$')
RUST_MODIFIER = re.compile(r'\b(?:use|impl|mut|dyn)\s+std$')
LINE_START = re.compile(r'(?:^|\n)[ \t]*std$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0)
    _, recent, position = carry
    value = -0.33 if position == 0 and token.strip().isalpha() else 0.0
    if token == '::':
        match = IDENTIFIER.search(recent)
        if match:
            name = match[1]
            if name == 'std':
                if RUST_MODIFIER.search(recent):
                    value = 10.0
                elif LINE_START.search(recent):
                    value = 15.0
                else:
                    value = 13.4
            elif name.islower():
                value = 0.3
            else:
                value = -0.35
    elif token == ':' and recent == 'Title' and position == 1:
        value = 11.75
    return (doc, (recent + token)[-120:], position + 1), value

"""Estimate layout-separator activity from the preceding text.

Ordinary text is near zero. Line wraps within prose, especially printed
backslash-n escapes, are positive; the newline after a chat message is negative.
Backticks amid nonbreaking spaces and an initial title-label colon are also
recognized. A small rolling context distinguishes prose from code. Split escape
sequences are recognized across token boundaries. State resets per document.
"""
import re

READS = ()
FUNCTION_WORDS = frozenset('''the a an of in on to with for from and or as by at
that is be are was were its their which'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, recent, previous = carry
    line = recent.rsplit('\n', 1)[-1].rsplit('\\n', 1)[-1]
    split_escape = previous.endswith('\\') and s.startswith('n')
    if split_escape:
        line = line[:-1]
    carry = (doc, (recent + s)[-300:], s)

    if s == ':' and recent == 'Title':
        return carry, 14.414
    if s == '\n' and previous == '<|im_end|>':
        return carry, -0.72 if len(line) <= 46 else -1.44

    words = line.split()
    unfinished = bool(words) and words[-1].lower() in FUNCTION_WORDS
    indent = len(line) - len(line.lstrip())
    length = len(line)
    value = 0.0
    if '\\n' in s or s.endswith('\\') or split_escape:
        value = escape_value(recent, line)
        if s.endswith('\\') and s[:-1].strip():
            ending = s[:-1].rstrip()[-1]
            if ending in '.!?':
                value = min(value, 0.70)
            elif ending not in ',-':
                value = min(value, 0.25)
    elif s == '\n':
        if unfinished:
            value = 1.81 if length > 55 and indent == 0 else 0.48
        elif len(words) > 10 and length <= 100:
            value = 0.60
    elif '\n' in s:
        if s.isspace():
            if unfinished:
                value = 1.30 if s.count('\n') == 1 else 0.13
            elif 46 < length <= 106:
                if s.count('\n') > 1 or indent:
                    value = 0.10
                else:
                    value = 0.90 if len(s) <= 2 else 1.60
        else:
            head = s.rstrip('\r\n')
            if s.count('\n') == 1:
                if head == '-':
                    value = 0.67
                elif head.endswith(','):
                    value = 0.16
    elif '`' in s and '\xa0' in recent:
        value = 2.75 if len(s) == 1 else 1.40
    elif s.isspace():
        if s.count('\xa0') >= 3:
            value = -0.55
        elif indent > 4 and len(words) > 9 and len(s) == 1:
            value = 0.27
    return carry, value


def escape_value(recent, line):
    # Braces, assignments and identifier underscores indicate code, not prose.
    words = line.split()
    escapes = recent.count('\\n')
    if '{' in recent or '}' in recent:
        return 0.53 if line.rstrip()[-1:] in (',', ':', ';') else 0.06
    if len(words) <= 6:
        if '=' in recent:
            return 0.14
        if escapes <= 3:
            return 0.46
        if recent.count('"') + recent.count("'") > 1 or '`' in recent:
            return 0.30
        return 1.83
    if escapes <= 1:
        return 0.10 if escapes == 0 else 1.45
    if '_' in recent:
        return 0.57
    context_words = re.findall('[A-Za-z]+', recent.lower())
    common = sum(w in FUNCTION_WORDS for w in context_words)
    if common <= 0.1 * len(context_words):
        return 1.38
    return 4.47 if words[-1].lower() in FUNCTION_WORDS else 3.80

programs.haiku:
"""Line breaks in running English prose.

The component writes a "line break here" signal into the residual stream. It is
strongest where a sentence is hard-wrapped at roughly 60-90 characters and the
wrap falls mid-sentence, after a function word such as "the", "of" or "to". The
escaped form of the same break, a backslash followed by n inside a JSON-style
string, is strongest in prose and silent in dense escaped code. A chat turn's
newline, right after <|im_end|>, pushes the other way.
"""
READS = ()

FUNCTION_WORDS = set(
    "the of to a an by in and that is be for with on at from as or which this its "
    "his her their our your it was are were has have not into than".split()
)
SENTENCE_END = ".!?:;"


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    new_document = len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_document:
        col, word, prev, recent = 0, "", "", ()
    else:
        col, word, prev, recent = carry
    prose = word != "" and word[-1] not in SENTENCE_END
    fw = word.lower() in FUNCTION_WORDS
    is_backslash = s.endswith("\\") and not s.endswith("\\\\")
    is_escaped_n = prev.endswith("\\") and s.startswith("n")
    is_escape_break = is_escaped_n or s == "\\n"
    is_real_break = "\n" in s and s != "\n\n"
    dense_code = sum(recent) >= 3   # many backslashes lately: JSON-escaped code, not prose

    value = 0.0
    if prev == "<|im_end|>" and is_real_break:
        value = -1.0
    elif is_backslash:
        if prose and not dense_code:
            value = 1.5 if fw else 0.5
    elif is_escape_break:
        if prose and not dense_code:
            value = 4.0 if fw else 1.0
    elif is_real_break:
        if prose and 60 <= col < 90:
            value = 1.2 if fw else 0.2
    elif "`" in s:
        value = 0.3

    if is_real_break or s == "\\n":
        col = 0
    else:
        col += len(s)
    if s.strip() and "\\" not in s:
        word = s.strip()
    recent = (recent + (is_backslash,))[-25:]
    return (col, word, s, recent), value

programs.sol:
"""A surface-form detector centered on the wait/ait syllable.

English wait-family words are strongly negative, with case and token-boundary
adjustments.  Split ait/eit and w...t syllables can respond too, even in
unrelated words.  A French-frequency check exempts familiar -ait inflections.
Some consonant + it fragments and ita/ito endings are weakly positive.
Chinese waiting words and Japanese katakana ito have small negative values.
Everything else is zero.  State stores only the current word, reset per document.
"""
import re
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


def french_imperfect(stem, word):
    frequency = zipf_frequency(word, 'fr')
    if len(stem) >= 3:
        frequency = max(
            frequency, zipf_frequency(stem + 'er', 'fr'),
            zipf_frequency(stem + 'ir', 'fr'),
            zipf_frequency(stem + 're', 'fr'))
    return frequency >= 2.6


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    fragment = anyascii(token)
    match = re.search(r'[^\W\d_]+$', previous + token)
    word = match[0][-50:] if match else ''
    continuing = bool(previous and fragment and fragment[0].isalpha())
    lower = anyascii(word).lower()
    bare = fragment.strip(' ._\t\r\n')
    value = 0.0

    if re.fullmatch(r'wait(?:s|ed|ing|er|ers)?', bare, re.I):
        if bare.lower() == 'wait':
            if bare.isupper():
                value = -8.5
            elif bare[0].isupper() and not token.startswith(('.', '_')):
                value = -5.8 if token[:1].isspace() else -4.8
            else:
                value = -7.9
        else:
            value = -5.8
    elif lower.startswith('wait') and continuing:
        value = -5.8
    elif re.fullmatch(r'await(?:s|ed|ing)?', bare, re.I):
        value = -0.4
    elif re.fullmatch(r'bait(?:s|ed|ing)?', bare, re.I):
        value = -8.2
    elif token in {'待', '等待'}:
        value = -1.9
    elif token == 'イト':
        value = -2.2
    elif continuing and regex.fullmatch(
            r'[\p{Latin}\p{Greek}\p{Cyrillic}]+', token):
        f = fragment.lower()
        if re.fullmatch(r'(?:a?it|a?its|ite|ites|iten|itet|t|te|ten)', f):
            if re.search(r'bait', lower):
                value = -12.0
            elif f == 'ait':
                proper_name = len(previous) <= 2 and previous[0].isupper()
                if proper_name or not french_imperfect(
                        previous.lower(), word.lower()):
                    value = -7.5
            elif re.search(r'(?:ai|ay|ei|ey)t', lower):
                value = -2.5
            elif previous.lower().endswith('w'):
                value = -2.5
            elif previous[-1:].lower() in 'rlmn' and f.startswith('it'):
                value = 0.7
        if re.fullmatch(r'it[ao]s?', f):
            value = -0.8 if previous[-1:].lower() in 'aeiou' else 1.1
        if re.search(r'w(?:ar|al|it|rit)t', lower) and re.fullmatch(
                r'(?:art|arten|alt|alter|ter|ten|et|eten|itt|itten)', f):
            value = -3.0
    return (document, word), value

"""Approximate several local cues rather than one unified semantic feature.

Personal future statements, learning/qualifications, recruitment phrases and
academic course codes give negative values. 'Wait' gives a positive value.
Clock minutes ending in zero are another strong negative cue. Only a short
phrase history is retained, and it is reset at each document boundary.
