import re

READS = ()
LEARNING = {'learn', 'learning', 'taught', 'studying', 'training', 'study', 'studies'}
ASSETS = {'skills', 'skill', 'knowledge', 'expertise', 'experience', 'qualifications'}
EVENTS = {'courses', 'workshop', 'seminar', 'lecture', 'curriculum'}
ROLES = {'student', 'students', 'learner', 'learners', 'participant',
         'participants', 'candidate', 'candidates', 'assistant', 'teacher',
         'instructor', 'applicant', 'applicants'}
WORK = {'job', 'jobs', 'candidate', 'candidates', 'applicant', 'applicants',
        'salary', 'duties', 'responsibility', 'responsibilities', 'position',
        'employment', 'certification'}
COURSE_NUMBER = re.compile(
    r'\b(?:MATH|CHEM|PHYS|BIOL|EBIO|ENGL|ECON|PSYC|'
    r'HIST|COMP|CS) ?\d{0,4}$')



def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, (), '')
    _, recent, tail = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    w = word.lower()
    prev = recent[-1] if recent else ''
    last = prev.lower()
    before = recent[-2].lower() if len(recent) > 1 else ''
    value = 0.0

    if w in {'will', "'ll", '’ll'}:
        value = -0.25
        if last in {'i', 'you', 'we'}:
            value -= 0.39
            if last == 'you':
                value -= 0.44
            if prev[0].isupper() and last != 'i':
                value -= 0.39
        if last == 'they':
            value -= 0.10 + (0.39 if prev[0].isupper() else 0)
        if last in {'it', 'this', 'that', 'there'}:
            value += 0.13
        if w != 'will':
            value += 0.42
        if last in ROLES:
            value -= 0.83
        if last in EVENTS | {'course', 'program', 'programme', 'exhibition'}:
            value -= 0.86
    elif w in {'wait', 'waiting'}:
        value = 0.47 if w == 'wait' else 0.29
    elif w in LEARNING:
        value = -0.20
        if last in {'to', 'can', 'will', 'you'}:
            value -= 0.32
    elif w in ASSETS:
        value = -0.17
        if w in {'skill', 'skills', 'expertise'}:
            value -= 0.08
        if w == 'experience':
            value -= 0.32
            if 'years' in [s.lower() for s in recent[-3:]]:
                value -= 0.82
        if last in {'of', 'have', 'has', 'your', 'our', 'their', 'practical',
                    'excellent', 'strong', 'interpersonal', 'communication'}:
            value -= 0.36
    elif w == 'course':
        value = -0.66
        if last == 'of':
            value += 0.63
        elif last in {'this', 'that'}:
            value -= 0.94
        elif last in {'the', 'a', 'our'}:
            value -= 0.11
    elif w in EVENTS:
        value = -0.44
    elif w in WORK:
        value = -0.14
    elif w in {'interested', 'willing', 'able', 'comfortable', 'confident'}:
        value = -0.03
        if last in {'am', 'is', 'are', 'was', 'were', "'m", "'re"}:
            value -= 0.28
        if w == 'interested':
            value -= 0.31
            if last in {'am', 'are', "'m", "'re"}:
                value -= 0.42
            if last == 'be':
                value += 0.26
        if w == 'able' and last == 'be' and before in {'should', 'must'}:
            value -= 1.05
    elif w in {'become', 'becoming'}:
        value = -0.13
        if last == 'to':
            value -= 0.46
        elif last in {'has', 'have'}:
            value += 0.24
    elif w in {'minimum', 'least'}:
        value = -0.23
    elif w == 'have' and last in {'must', 'should'}:
        value = -0.54
    elif w == 'for' and last in {'looking', 'responsible'}:
        value = -0.80
    elif w in {'a', 'an'}:
        if last == 'for' and before in {'looking', 'look'}:
            value = -0.92
        elif last in {'seeking', 'for'}:
            value = -0.16
    elif w == '/or':
        value = -0.37
    elif w == 'interests' and last == 'research':
        value = -1.51

    if w in {'description', 'information', 'requirements'} and any(
            s.lower() in {'course', 'admissions', 'admission'} for s in recent[-3:]):
        value -= 1.29
    if token.isdigit():
        joined = tail + token
        if re.search(r'\d{1,2}:\d{2}$', joined):
            value -= 0.21
            if token == '0':
                value -= 0.69 + (0.48 if tail.endswith(':0') else 0)
        elif re.search(r'\d\.\d{2}$', joined):
            value -= 0.05 + (0.13 if token == '0' else 0)
    if token.isspace() or token.isdigit():
        if COURSE_NUMBER.search(tail):
            value -= 1.20
    return (doc, (recent + (word,))[-5:], (tail + token)[-64:]), value

programs.haiku:
"""Layer 1, down_proj component 2890: it reads mainly MLP hidden unit 2890 (about half of
its input weight) and writes a fixed direction into the residual stream. Its activation
is sparse and mostly quiet, with two faces:

* Negative when the text is addressing a reader about what they will do, learn or
  need: "you WILL be", "students should be ABLE to", "skills", "learn", "course",
  "interested", "'ll", "experience". Strongest right after "you"/"students"/
  "candidate" (within the last three tokens).
* Positive on a few named-entity and title words: "Wait", month names, US places,
  job titles ("Director", "Chief", "staff", "Office"), and "of" right after such a
  title ("suite OF", "president OF", "Director OF").

A document's first token is slightly negative. Everything else sits near zero.
Values are the rounded group means of a least-squares fit on 2048 training rows.
Known gap: most of the unit's variance is diffuse small activity (about ±0.1) on
ordinary tokens that these word lists do not capture.
"""

READS = ()

READER = {"you", "You", "your", "Your", "students", "Students", "student",
          "candidate", "Candidate", "learners", "participants", "applicants"}
MODAL = {"will", "'ll", "’ll", "shall", "would", "should", "must", "can", "could", "may", "might"}
LEARN = {"learn", "learning", "learned", "skills", "skill", "knowledge", "experience",
         "course", "courses", "interests", "interested", "able", "become", "comfortable",
         "opportunity"}
MONTHS = {"January", "February", "March", "April", "May", "June", "July", "August",
          "September", "October", "November", "December"}
PLACES = {"California", "Washington", "Florida", "Texas", "Colorado", "Michigan", "Ohio",
          "Virginia", "Carolina", "York", "Jersey", "CA", "NY", "NJ", "WA", "TX", "FL"}
TITLES = {"Director", "director", "Chief", "Officer", "Staff", "staff", "Office", "office",
          "president", "President", "Advisor", "Assistant", "Manager", "Editor", "editor",
          "Coach", "coach", "Professor", "professor", "suite", "father"}


def step(carry, prefix, upstream):
    words = [s.strip() for s in prefix.token_strings]
    word = words[-1]
    prev = words[-2] if len(words) > 1 else ""
    if len(words) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, -0.07
    near_reader = any(w in READER for w in words[-4:-1])
    if word in MODAL or word in LEARN:
        if word in MODAL:
            return carry, (-0.3 if near_reader else -0.05)
        return carry, (-0.65 if near_reader else -0.25)
    if word in ("Wait", "wait"):
        return carry, 0.5
    if word == "of" and prev in TITLES:
        return carry, 0.2
    if word in MONTHS or word in PLACES or word in TITLES:
        return carry, 0.15
    return carry, 0.0

programs.sol:
"""Short word-initial verb-like pieces, especially in Arabic.

Arabic imperfect prefixes (teh, yeh, noon, alef/hamza) give negative
contributions. Conjunctions and one-letter prepositions can precede them.
Negation and relative/subject cues strengthen the response; prepositions
weaken it.
Persian spelling changes the response to isolated word-initial teh to positive.
Smaller rules cover Hebrew person-prefix letters, Chinese modal/question
words, 'it looks/seems', and the colon of a document-opening 'Title:'.
These are surface cues, not a grammatical parser. Other tokens get a near-zero
baseline, and all state resets at document boundaries.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', False, 0)
    _, persian, previous, previous_start, position = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    # Keep language evidence for the next hundred tokens, within this document.
    persian = max(0, persian - 1)
    if (any(ch in 'پچژگکی' for ch in token) or
            word.lower() in ('persian', 'farsi') or
            (previous_start and token[:1].isspace() and
             previous.strip() in ('در', 'از', 'را', 'است', 'كه', 'اين'))):
        persian = 100
    boundary = (token[:1].isspace() or not previous or
                (previous[-1] != '\ufffd' and
                 unicodedata.category(previous[-1])[0] not in 'LM'))
    clitic = (previous_start and
              previous.strip() in ('و', 'ف', 'ب', 'ل', 'ما', 'س'))
    # Waw/fa can be attached conjunctions; fi- is instead a preposition.
    body = word
    if boundary and len(body) > 1 and body[0] in 'وف' and not word.startswith('في'):
        body = body[1:]
    value = 0.003
    if ((boundary or clitic) and
            body not in ('في', 'أن', 'أو', 'أي', 'أم', 'يا')):
        if persian:
            if body == 'ت':
                value = 1.5
            elif body == 'ی':
                value = -0.9
        elif body and (len(body) <= 2 or body in ('تست', 'يست')):
            # Person prefixes t-, y-, n-, and hamza; then future s-.
            if body[0] == 'ت':
                value = -6.0 if body != 'تم' else -2.7
            elif body[0] == 'ي':
                value = -6.3 if len(body) == 1 else -4.9
            elif body[0] == 'ن':
                value = -4.4
            elif body[0] == 'أ':
                value = -2.8
            elif body[0] == 'س':
                value = -7.2 if body == 'ست' else (-4.6 if body == 'سي' else -1.9)
            elif body == 'ا':
                value = -1.0
            elif body == 'آ':
                value = -1.6
    if value < -2 and not persian and body[:1] in 'تينأ' and body != 'يست':
        cue = previous.strip()
        if cue[:1] in 'وف' and cue not in ('و', 'ف'):
            cue = cue[1:]
        if (cue in ('أن', 'لا', 'لم', 'لن', 'لما', 'نحن', 'أنا') or
                (cue.startswith(('إن', 'أن', 'لكن')) and
                 cue.endswith(('نا', 'ني')))):
            value = min(value, -9.0)
        elif cue in (
                'التي', 'التى', 'الذي', 'الذين', 'هل', 'كيف', 'كنت'):
            value = min(value, -8.0)
        elif cue in ('في', 'إلى', 'الى', 'من', 'عن', 'على', 'مع'):
            value *= 0.6
    if value < -2 and clitic and previous.strip() in ('ب', 'ف'):
        value *= 0.5
    if value < -2 and clitic and previous.strip() == 'س':
        value = -8.0
    if position == 0 and not token[:1].isspace() and value < -1:
        value = -0.3
    # The corresponding Hebrew person-prefix letters are negative too.
    if boundary:
        if word == 'ת':
            value = -5.5
        elif word == 'י':
            value = -4.1
        elif word == 'נ':
            value = -3.5
    # Clause-initial 可 often means 'but'; internally it means 'can'.
    if word == '可':
        value = 2.4 if boundary else 1.0
    elif word == '怎么':
        value = 1.4
    elif word == '应该':
        value = 0.9
    elif word == '见':
        value = 1.2
    elif word == '再':
        value = 0.7
    elif word in ('looks', 'seems') and previous.strip().lower() == 'it':
        value = 1.0
    elif token == ':' and position == 1 and previous == 'Title':
        value = 8.736
    return (doc, persian, token, boundary or clitic, position + 1), value

"""JavaScript object openings versus multiline code-block openings.

Object arguments, initializers and const/let destructuring give positive
pulses; multiline block braces give negative pulses. Nearby language cues
filter some Python, TeX and quoted-JSON lookalikes. Additional lexical tests
cover JavaScript names, Golang, and g+or/ur/aur/uri spellings (Imgur is stronger).
Most other tokens give zero. A trailing 256-character buffer resets per document.
"""
import re

READS = ()
JS = re.compile(r'\b(const|let|var|function|export|require|async)\b|=>|\bthis\.')
PY = re.compile(r'\b(def|print|elif|None|True|False)\b|\b(pd|gpd|json|self)\.')
MATH = re.compile(
    r'\\(left|right|frac|sqrt|mathrm|mathbf|mathbb|text|begin|psi|vec|'
    r'eta|mu|displaystyle|scriptscriptstyle|inf|sup)\b')
SYSTEMS = re.compile(
    r'std::|#include|\bnullptr\b|->|\bfn\b|unwrap|let mut|format!|\.iter\(\)')


def activation(token, recent):
    p = recent.rstrip()
    if token == '.js':
        return 7.1 if re.search(r'\bNext$', p) else 2.0
    if token in ('js', 'javascript'):
        return 2.9 if p.endswith('```') else 0.9
    if token == '.exports' and re.search(r'\bmodule$', p):
        return 5.0
    if token == ' require' and p.endswith('='):
        return 0.7
    if token == 'olang' and recent.endswith(('G', 'g')):
        return -2.4
    if recent.lower().endswith('g'):
        if token == 'ur':
            return 10.3 if recent.lower().endswith('img') else 5.7
        if token in ('or', 'aur', 'uri'):
            return 4.5
    multiline = '\n' in token or token.endswith('\\')
    if multiline and token.strip(' \r\n\\') in ('(', '['):
        return -0.7
    if '{' not in token or any(c in token for c in '$%_`'):
        return 0.0
    head, after = token.rsplit('{', 1)
    if after.strip(' \r\n\\'):
        return 0.0
    nl = '\n' in after or after.endswith('\\')
    js = bool(JS.search(recent))
    py = bool(PY.search(recent)) and not js
    math = bool(MATH.search(recent[-128:])) or p.endswith('$')
    if '{' in head and '=' in head:
        return 7.0 if nl else -0.3
    if head.strip() == '=':
        return 0.4  # JSX attribute expression, not an object literal.
    if head.rstrip().endswith('('):
        if head.startswith(' ') and not p.endswith(('=>', '=', 'return')):
            return 0.0
        return 0.0 if math or py or SYSTEMS.search(recent) else 5.8
    if head.rstrip().endswith('['):
        return 0.0 if math else 4.0
    if ',' in head:
        return 0.0 if math else (4.0 if nl or js else 0.0)
    if head.rstrip().endswith(')') or p.endswith('=>'):
        return -1.2 if nl else -0.1
    if head.strip() or math:
        return 0.0
    if re.search(r'\)\s*const$', p):
        return -1.3 if nl else 0.0
    if re.search(r'\b(const|let|var)$', p):
        return 9.5
    if re.search(r'@(?:param|return)$', p):
        return 1.8
    if re.search(r'\breturn$', p):
        return 0.0 if py else 5.8
    if p.endswith('='):
        return 6.0 if js else 0.0
    if p.endswith((',', '[', '(')):
        return 0.0 if py else (4.5 if nl or js else 1.0)
    if p.endswith(':'):
        if p.endswith(('":', "':")):
            return 1.0
        return 0.0 if py else (3.0 if nl else (4.4 if js else 0.0))
    if nl:
        return -0.2 if token == '{\\' else -1.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (recent + token)[-256:]), activation(token, recent)

"""Approximate a source-line opening feature, with a title-header exception.

Indentation and the keywords opening declarations, imports and conditionals
receive positive values. Three-space chunks are a strong indentation cue: the
last space of a four-space indent can belong to the following word token. Ordinary running text is near zero. Formatting at a
fresh document has its own response; notably, the colon in an initial `Title:`
header is exceptionally large. State tracks only formatting and a package
declaration, and resets at document boundaries. Fine lexical variation,
especially the first ordinary word of a document, is intentionally omitted.
"""
READS = ()
DECLARATIONS = {'const', 'let', 'var'}
FUNCTIONS = {'func', 'function'}
VISIBILITY = {'public', 'protected'}
TYPES = {'int', 'float', 'double', 'long', 'short', 'char', 'byte',
         'bool', 'boolean', 'void', 'string', 'String', 'auto'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos, indentation, previous, packaged, leading_cr = 0, True, '', False, True
    else:
