    word = s.strip()
    separated = bool(previous) and not previous.strip(' \t')
    opening = indentation or separated
    fresh_line = indentation and not separated
    if word == 'package' and opening:
        packaged = True

    value = 0.0
    if s and not s.strip(' '):
        n = len(s)
        if n % 4 == 3:
            value = (0.60 if n == 3 else 1.3 / n) if fresh_line else (
                0.16 if n == 3 else -0.03)
        elif n == 1:
            value = 0.20 if fresh_line else 0.0
        elif n == 2:
            value = 0.07 if fresh_line else 0.0
        else:
            value = (-0.10 if fresh_line else 0.08) if n % 4 == 0 else 0.0
    elif s and not s.strip(' \t'):
        if ' ' in s:
            spaces = s.count(' ')
            value = 0.03 if spaces % 4 == 3 else (
                -0.10 if spaces == 1 else -0.38)
        else:
            value = -0.055 * min(len(s) - 1, 3)
    elif opening:
