            value = 1.0 if s == word else 1.4
        elif word in FUNCTIONS:
            value = 0.75
        elif word in VISIBILITY:
            value = 0.70
        elif word == 'if':
            value = 0.50
        elif word in TYPES:
            value = 0.60
        elif word == 'import':
            value = 2.15 if packaged else 0.55
        elif word in {'using', 'use'}:
            value = 0.80
        elif word == 'from':
            value = 0.45
        elif word == 'def':
            value = 0.20

    elif s.startswith('\t'):
        if word in DECLARATIONS:
            value = 0.80
        elif word in FUNCTIONS:
            value = 0.40
        elif word in VISIBILITY or word in TYPES:
            value = 0.60
        elif word == 'if':
            value = 0.32
    if word == 'import' and s.startswith('\t'):
        value = 0.25
    if word == 'return':
        value = -0.05 if s.startswith(' ') else -0.14

    if pos == 0:
        value = -0.12
        if s and not s.strip(' '):
