"perhaps" and "maybe" and for the chat-role word "assistant"; everything else is 0.
"""

# Tokens that open code, markup or a comment.
CODE_OPENERS = {
    "#", "##", "###", "#!/", "#include", "//", "/*", "/*\n", "<!", "--",
    '"""', "'''", "import", "package", "from", "const", "class",
}
HEDGES = {"perhaps", "maybe", "Perhaps", "Maybe"}
CHAT_TOKENS = {"<|im_start|>", "<|im_end|>", "<|endoftext|>"}


def opening_value(tok):
    """Activation for a token that opens a document (it has no earlier context)."""
    if tok in CODE_OPENERS:
        return 5.0
    if tok in CHAT_TOKENS:
        return -0.6
    if tok.strip() == "":
        return 2.2                      # whitespace-only token
    first = tok.lstrip()[:1]
    if first.isdigit():
        return 1.4
    if first.isalpha():
        if tok.startswith(" "):
            return 0.1                  # mid-sentence fragment
        return -0.3 if first.isupper() else 0.2   # capitalised prose opening
    if ord(first) > 127:
        return -0.2                     # non-Latin script
    return 1.4                          # other punctuation or symbols


