@lru_cache(maxsize=32768)
def modifiers(token, initial=False):
    word = token.strip()
    if not (word.isascii() and word.isalpha() and len(word) > 1):
        return 0.0
    senses = wordnet.categories(word)
    if initial:
        return (-0.035 * ('adj.all' in senses)
                - 0.05 * ('adv.all' in senses))
    return (-0.006 * ('adj.all' in senses)
            - 0.002 * ('adv.all' in senses)
            + 0.010 * ('adj.pert' in senses))


