    if token == '\x00':
        return 1.9424
    if token == '<!':
        return 3.18
    if token == '(function':
        return 0.338
    if token == '··':
        return 0.47
    if token == '^^^^':
        return 1.33
    if token.startswith('<|'):
        return 0.01
    if token.isspace():
        if '\n' in token or '\r' in token:
            return 0.24
        return 0.10 if token == ' ' else 0.37
    word = token.strip()
    if word.isascii() and word.isdigit():
        return 0.15
    if word and all(c in '.,:;!?…' for c in word):
        return 0.18
    if word and all(c in '\'"`“”‘’' for c in word):
        return 0.28
    if word.isascii() and word.isalpha() and word.isupper():
        return 0.18
    if word and any(c.isalnum() for c in word) and not word[0].isalnum():
        return -0.12
