The response decays with the number of intervening tokens. Letter-containing
or multi-character separators and intervening newlines weaken it; a colon
strengthens it, and a hyphen weakens it. Uninterrupted digit runs are nearly
zero, with slight suppression on an identifier's second digit. Other tokens
are zero except for a negative document-start value. This is a local numeric
pattern detector, not arithmetic.
"""

from math import exp

READS = ()
DIGITS = '0123456789'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        age, gap_newline, previous, earlier = 40, False, '', ''
    else:
        _, age, gap_newline, previous, earlier = carry
    # age counts non-digit tokens since the most recent digit.
    token = prefix.token_strings[-1]
    value = 0.0
    if len(token) == 1 and token in DIGITS:
        if age == 0:
            if any(c.isalpha() for c in earlier):
                value = -0.20 if any(c.isupper() for c in earlier) else -0.08
        else:
            strength = 1.05
            if any(c.isalpha() for c in previous):
                strength -= 0.37
            if len(previous) > 1:
                strength -= 0.26
            if gap_newline:
                strength -= 0.40
            if previous == ':':
                strength += 0.40
            elif previous == '-':
                strength -= 0.34
            value = 0.10 + strength * exp(-0.50 * (age - 1))
        age, gap_newline = 0, False
    else:
        age = min(age + 1, 40)
        gap_newline = gap_newline or '\n' in token
    if first:
        value = -0.26
    return (doc, age, gap_newline, token, previous), value

