"""layers.1.mlp.down_proj:2909: the "first digit of a number" detector.

What it does: fires on the first digit of a number (a digit whose previous token is
not a digit). Qwen writes numbers one digit per token, so "2015" is "2","0","1","5", and
the component responds to the "2" but is near zero on "0", "1", "5" and on every
non-digit token. Its strength depends on the context just before the number:
- A number that follows another number across one separator, as in "3.0", "5,000",
  "9:30", "12/5", is strongest (about 1.1).
- A number after a month name ("June 2", "March 1") is strong (about 1.3).
- A number after a symbol or punctuation ("$5", "(5", "= 5") is moderate (about 0.33).
- A number after a word and a space ("about 5", "in 2015") is moderate (about 0.3);
  after a comma and a space ("1, 2, 3") a little higher (0.5).
- A number after indentation or a run of spaces, as in code, is nearly zero (0.07).
- A number that comes a few tokens after another number ("2 and 3", "1-2"), without
  a separator directly between them, gets a boost (+0.25).
"""

READS = ()

MONTHS = set("January February March April May June July August September October November December Jan Feb Mar Apr Jun Jul Aug Sep Sept Oct Nov Dec".split())
MONTHS = MONTHS | set(" " + m for m in MONTHS)
PUNCT = set([",", ".", ":", "\xa0", "/", "+", "-", " -", "[", "=", ";", "(", "$", "**", "\n"])


def _is_digit(s):
    return len(s) == 1 and s in "0123456789"


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    if not _is_digit(cur) or (len(toks) > 1 and _is_digit(toks[-2])):
        return carry, 0.0          # not the first digit of a number
    before = toks[-2] if len(toks) > 1 else ""
    before2 = toks[-3] if len(toks) > 2 else ""
    if _is_digit(before2):
        value = 1.1                # "3.0", "5,000", "9:30": number continues a number
    elif before2 in MONTHS:
        value = 1.3                # "June 2", "March 1"
    elif before in PUNCT:
        value = 0.33               # "$5", "(5", "= 5"
    elif before == " ":
        if before2 == ",":
            value = 0.5            # a number after a comma: "1, 2, 3"
        elif before2.strip():
            value = 0.3            # "about 5", "in 2015"
        else:
            value = 0.07           # after indentation or a run of spaces, as in code
    else:
        value = 0.12
    if not _is_digit(before2) and any(_is_digit(x) for x in toks[-5:-2]):
        value += 0.25              # another number a few tokens back
    return carry, float(value)

