        return -7.5
    if low == 'spare':
        return -1.2
    if low == 'pent':
        return -1.6
    if s in ('废', '廢'):
        return -5.8
    if s in ('浪费', '浪費', '废物', '廢物'):
        return -2.0
    if s in ('费', '費'):
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = activation(previous, token)
    # Only keep the current alphabetic word; punctuation and spaces break it.
    text = previous + token if token[:1].isalpha() else token
    match = WORD_END.search(text)
    tail = match.group()[-32:] if match else ''
    return (doc, tail), value

"""Sparse lexical-pattern approximation, not a general semantic classifier.

It fires strongly on GitHub domain endings, more weakly on JSON key colons
and a few programming-language junctions.  Formatted numbers and document
openers have separate rules, as do third-level Markdown headings.
Unmatched positions are zero except for a small document-start baseline.
