READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, age = '', 0
    else:
        _, tail, age = carry
    token = prefix.token_strings[-1]
    fresh = age == 0 or tail.endswith('<|endoftext|>')
    value = -0.27 if fresh else 0.0

    # Recognizable document-opening syntax.
    if fresh:
        if token == 'Title':
            value = -2.07
        elif token.startswith(('"""', "'''")):
            value = -2.1
        elif token.startswith('/*'):
            value = -0.8 if '\n' in token else -1.5
        elif token == '#':
            value = -0.71
        elif token in ('int', 'string', 'char'):
            value = -2.7
        elif token == 'import':
            value = -0.87
    elif token == ':' and (
        tail == 'Title' or tail.endswith('<|endoftext|>Title')
    ):
        value = -2.76

    # Hosting URLs, Go module paths and repository API paths.
    if token == '.com' and tail.lower().endswith('github'):
        value = 2.0 if tail.endswith('://github') else 1.5
        if tail.endswith('"github'):
            value = 1.95
    elif token == '.com' and tail.endswith('githubusercontent'):
        value = 1.7
    elif token == '.org' and tail.endswith('bitbucket'):
        value = 0.9
    elif token == '/repos' and tail.endswith('github.com'):
        value = 0.93
    elif token == '/wiki' and tail.endswith('wikipedia.org'):
        value = 0.54
    elif token == '/github' and tail.endswith('go-'):
        value = 0.72

    # The quote-colon boundary after a JSON property name.
    elif token == '":':
        key = re.search(r'"([A-Za-z_]+)$', tail)
        if key:
            value = {'name': 0.27, 'arguments': 0.075,
                     'command': 0.05}.get(key[1], 0.04)

    # A third-level Markdown heading on a new line.
    elif token == '###' and tail.endswith('\n'):
        value = -0.38

    # Import/package declarations in Java and JavaScript.
    elif re.search(r'\bimport$', tail):
        if token == ' static':
            value = 1.45
        elif token in (' java', ' org'):
            value = 0.24
        elif token == ' {':
            value = 0.28
    elif token == ' com' and re.search(r'\bpackage$', tail):
        value = -0.78

    # Thirty and the end of a three-digit thousands group.
    elif token == '0' and re.search(r'(?<!\d)3$', tail):
        value = -0.16
    elif token.isascii() and token.isdigit():
        if re.search(r'\d,\d{2}$', tail):
            value = 0.12 if token != '0' else 0.24

    return (doc, (tail + token)[-100:], age + 1), value

"""AL/ALL word pieces, including split and transliterated spellings.

Short unfamiliar pieces are stronger than long familiar tokens, using English
frequency estimates. A-L, A-IL and A-UL can straddle a token boundary; the
response then fades on continuations. UTF-8 fragments are joined first.
Romanization ignores vowel marks, treats aleph/alif and IPA open O as A,
and folds Japanese R to L. Greek alpha-lambda gets a stronger response.
There is also a small negative document-start baseline and a separate large
response to a document-initial 'Title:' header.
"""
