@lru_cache(maxsize=16384)
def describe(raw):
    letters = ''.join(c for c in unicodedata.normalize('NFKD', raw)
                      if unicodedata.category(c) != 'Mn')
    letters = letters.replace('א', 'a').replace('ا', 'a').replace('ɔ', 'a')
    s = anyascii(letters).lower().strip().replace("'", '')
    if any('KATAKANA' in unicodedata.name(c, '') or
           'HIRAGANA' in unicodedata.name(c, '') for c in raw):
        s = s.replace('r', 'l')
    return s, zipf_frequency(s, 'en')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, old_frequency = '', 0.0
        pending, strength, was_first = b'', 0.0, False
    else:
        _, previous, old_frequency, pending, strength, was_first = carry
    buffer = pending + prefix.token_bytes[-1]
    raw, used = codecs.utf_8_decode(buffer, 'replace', False)
    pending = buffer[used:]
    s, frequency = describe(raw)
    joins = bool(raw and raw[0].isalpha()) and not first
    n, at = len(s), s.find('al')

    if s == ':' and previous == 'title' and was_first:
        value = 8.74
    elif at == 0:
        if n <= 3:
            value = (1.33 if frequency <= 2.5 else
                     0.52 if frequency <= 3.75 else 0.91)
        elif frequency <= 3.0:
            value = 0.65 if n == 4 else 0.31
            if 'al' not in raw.lower():
                value = 1.04
        else:
            value = 0.10
    elif first:
        value = -0.24
    elif 0 < at <= 3:
        if n <= 3:
            value = 0.40 if not joins or frequency <= 3.25 else 0.01
        else:
            value = 0.13 if at == 1 else 0.07
    elif joins and previous.endswith('a') and s.startswith(('l', 'il', 'ul')):
        value = (2.04 if old_frequency > 5.25 else
                 0.46 if frequency <= 4.75 else 1.34)
        if raw.startswith(('λ', 'Λ')):
            value = 4.5
        elif raw and not raw[0].isascii():
            value = max(value, 1.0)
    elif joins:
        value = 0.5 * strength
        if raw.startswith(('λ', 'Λ')):
            value = 0.8 * strength
        if previous.endswith(('al', 'all')):
            if n <= 2 and len(previous) <= 4:
                continuation = (0.61 if n == 2 else
                                1.5 if len(previous) <= 2 else 0.92)
                value = max(value, continuation)
            else:
                value = max(value, 0.31 if len(previous) <= 3 else 0.11)
    else:
        value = 0.0
    strength = max(0.0, value) if s != ':' else 0.0
    if not raw or all(unicodedata.category(c) == 'Mn' for c in raw):
        s, frequency = previous, old_frequency
    prediction = value * 1.15 if 0.0 < value < 8.0 else value
    return (doc, s, frequency, pending, strength, first), float(prediction)

"""A spelling-fragment detector for the sc/sk/sq family.

It recognizes clusters within a token or across a token boundary, including
related sibilant/consonant spellings in several scripts. Short, attached
fragments tend to score higher than long or familiar whole words. The rules
use letter shape, capitalization and corpus word frequency to
estimate strength. A fading echo continues into the next word pieces, with
a separate echo for dotted abbreviations. These are approximate spelling
rules, not a reconstruction of the MLP.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
CLUSTER = re.compile(
    r"[sz]h?[ckqg]|[сзшжщчц]ь?[кхц]|[σς][κχ]|ス[カキクケコ]"
)
SIBILANT = re.compile(r"(?:[sz]h?|[сзшжщчц]ь?|[σςスش]|스)$")
CONSONANTS = set("ckqgкхцκχカキクケコکك카키쿠케코커")


@lru_cache(maxsize=32768)
def normalize(text):
    unaccented = "".join(
        c for c in unicodedata.normalize("NFKD", text)
        if not unicodedata.combining(c)
    )
    return unicodedata.normalize("NFC", unaccented).lower()


@lru_cache(maxsize=32768)
def frequency(word):
    return zipf_frequency(word, "en")


def properties(s, p, pp, internal):
    t, pt, ppt = normalize(s), normalize(p), normalize(pp)
    if internal:
        match = list(CLUSTER.finditer(t))[-1]
        after = t[match.end():]
    else:
        after = t.lstrip(".-'")[1:]
    word_match = re.search(r"[^\W\d_]+$", ppt + pt + t)
    word = word_match.group() if word_match else ""
    raw_prefix = re.search(r"[^\W\d_]+$", pp + p)
    previous = pt.rstrip(".-'")
    return {
        "after_h": after.startswith("h"),
        "after_r": after.startswith("r"),
        "after_vowel": bool(after) and after[0] in "aou",
        "has_g": "g" in t or "х" in t,
        "has_k": "k" in t or "к" in t,
        "letters": sum(c.isalpha() for c in t),
        "prefix_capitalized": bool(raw_prefix and raw_prefix.group()[0].isupper()),
        "previous_vowel_s": len(previous) > 1 and previous[-2] in "aeiou",
        "tail": len(after),
        "token_frequency": frequency(t.strip()),
        "word_frequency": frequency(word),
    }


def boundary_score(f):
    # A short consonant fragment following an s-like ending.
    if f["letters"] <= 3:
        if f["has_g"]:
            return 0.43 if f["letters"] <= 1 else 0.10
        if f["after_h"]:
            return 0.81 if f["previous_vowel_s"] else -0.09
        return 3.57 if f["previous_vowel_s"] else 2.22
    # Longer, familiar continuations are much weaker.
    if f["tail"] <= 3:
        if f["token_frequency"] <= 3:
            return 2.08 if f["after_vowel"] else 0.69
        return 0.48 if f["word_frequency"] <= 3 else -0.06
    if f["after_r"]:
        return -0.01 if f["previous_vowel_s"] else -0.36
    return 0.42 if f["letters"] <= 5 else 0.14


def internal_score(f):
    # Clusters inside long tokens usually have little effect.
    if f["letters"] > 5:
        return 0.08
    if f["letters"] > 3:
        if f["word_frequency"] <= 2:
            return 0.09 if f["after_h"] else 0.56
        return 0.21
    # Short rare fragments, especially those ending at sk/sc, stand out.
    if f["word_frequency"] <= 3:
        if f["tail"] == 0:
            return 2.56 if f["has_k"] else 1.63
        return 1.30 if f["token_frequency"] <= 3 else 0.16
    if f["letters"] <= 2:
        return 1.59 if f["prefix_capitalized"] else 1.26
    return 0.87 if f["token_frequency"] <= 3 else 0.07


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        p = pp = ""
        old = older = 0.0
        previous_continues = False
    else:
        _, p, pp, old, older, previous_continues = carry
    s = prefix.token_strings[-1]
    t, pt, ppt = normalize(s), normalize(p), normalize(pp)
    internal = bool(CLUSTER.search(t))
    prior_sibilant = bool(SIBILANT.search(pt.rstrip(".-'")))
    # Also recognize a split sch-k spelling, but not ordinary ch-k.
    prior_sibilant |= pt.endswith("h") and bool(SIBILANT.search(ppt))
    boundary = prior_sibilant and t.lstrip(".-'")[:1] in CONSONANTS
    base = 0.0
    if internal or boundary:
        f = properties(s, p, pp, internal)
        base = internal_score(f) if internal else boundary_score(f)
    continues = bool(t[:1].isalpha())
    value = 1.0000 * base
    if continues:
        value += 0.4087 * old
        if previous_continues:
            value += 0.0588 * older
    if re.fullmatch(r"\.[A-Za-z]+", s):
        value += 0.2349 * old
    return (document, s, p, base, old, continues), float(value)

