import calendar
import re

READS = ()
MONTHS = set(calendar.month_name[1:]) | set(calendar.month_abbr[1:]) | {'Sept'}
DAYS = set(calendar.day_name) | set(calendar.day_abbr)
DATE_VERBS = {
    'dated', 'posted', 'updated', 'published', 'filed', 'received',
    'submitted', 'released', 'approved', 'created', 'ended', 'decided',
    'accepted', 'issued', 'edited', 'due',
}
RANGES = {'until', 'till', 'through', 'thru', 'to'}
DIGITS = str.maketrans('０１２３４５６７８９', '0123456789')
MONTH_PATTERN = re.compile(r'\b(?:' + '|'.join(MONTHS) + r')\b')


def cue(word):
    """Typical strength of a word introducing a date or time."""
    if word in DAYS:
        return 18.0 if len(word) == 3 else 10.0
    lower = word.lower()
    if lower == 'born':
        return 9.0
    if lower in DATE_VERBS:
        if lower == 'received' and word == lower:
            return 2.0
        return 10.0 if word[0].isupper() else 6.5
    return {'on': 4.4 if word == 'on' else 3.5, 'until': 3.7,
            'till': 3.7, 'from': 1.2, 'since': 0.5, 'around': 0.8,
            'at': 1.4, '@': 1.2, 'between': 0.5, 'le': 5.5,
            'vom': 6.4, 'today': 6.5, 'daily': 4.0}.get(lower, 0.0)


def predict(token, previous, before_previous, text):
    word = token.strip(' \t\r\n-')
    prev = previous.strip()
    digit = token.translate(DIGITS)
    if not (word in MONTHS or word in DAYS or word.lower() in RANGES
            or token == ' ' or token.strip() in {',', '.,', ':', '.', '··'}
            or (len(digit) == 1 and digit in '0123456789')):
