        if prev in DAYS:
            return -15.5
        if prev in {',', '.,', '('} and before_previous.strip() in DAYS:
            return -9.5
        if strength:
            if last.lower() == 'on':
                return -10.0 if combined else -6.2 if last == 'on' else -4.4
            if last.lower() == 'from':
                return -3.2
            if last.lower() == 'born':
                return -10.5
            return -strength
        if prev.lower() == 'in':
            return -0.5
        if prev.lower() == 'of':
            return -2.2
        if prev in {'th', 'st', 'nd', 'rd', ':'}:
            return -3.2
        if last.lower() in {'end', 'starting', 'online'}:
            return -6.0
        if previous.isspace() and re.search(r'\b(' + '|'.join(DAYS) + r')\s+$', text):
            return -9.5
        return -0.8
    if word in DAYS:
        return -4.0 if last.lower() == 'on' else -1.0
    if token == ' ':
        if previous.isspace():
            return 0.0
        if prev == ',' and before_previous.strip() in DAYS:
            return -9.5
        if prev == ',' and before_previous.strip().lower() in {'today', 'daily'}:
            return -6.0
        if prev.lower() == 'online' and re.search(r'published online$', text, re.I):
            return -9.0
        if combined:
            return -8.0
        if strength:
            return -strength
        if re.search(r'(posted|updated|published|created)\s*:$', text, re.I):
            return -5.8
        if re.search(r'(date|time)\s*:$', text, re.I):
            return -3.2
