                '年', '月', '日', '时', '時', '晚上', '早上', '上午', '下午')):
            return -3.5 if digit in '09' else -1.5
        return 0.0
    if token in {',', '.,'} and prev in DAYS and not text.endswith('the Sun'):
        return -9.0 if len(prev) == 3 else -3.5
    if token in {':', ' :'} and last.lower() in {'updated', 'posted', 'published', 'created'}:
        return -5.5
    if token == '.' and prev in MONTHS:
        return -3.0 if re.search(r'(filed|issued|on|dated) \w+$', text) else -1.0
    if word.lower() in RANGES:
        if prev in DAYS and word.lower() in {'through', 'thru'}:
            return -7.0
        if date and (prev.isdigit() or prev in MONTHS or prev in {'th', 'st', 'nd', 'rd'}):
            return -3.0 if word.lower() == 'to' else -5.0
        if word.lower() in {'until', 'till'}:
            return -4.5 if re.search(r'(1[5-9]\d{2}|20\d{2})$', text) else -0.7
    if token == '··':
        return -1.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '')
    _, previous, before_previous, text = carry
    token = prefix.token_strings[-1]
    value = predict(token, previous, before_previous, text)
    return (doc, token, previous, (text + token)[-160:]), value

