"""Date and clock-time detector: a negative response wherever the text is writing a
calendar date or a clock time, strongest on the clock's minutes digits and on the
space or month name that leads into a date."""
import unicodedata

MONTHS = {"January", "February", "March", "April", "May", "June", "July", "August",
          "September", "October", "November", "December", "Jan", "Feb", "Mar", "Apr",
          "Jun", "Jul", "Aug", "Sep", "Sept", "Oct", "Nov", "Dec"}
WEEKDAYS = {"Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday",
            "Mon", "Tue", "Tues", "Wed", "Thu", "Thur", "Thurs", "Fri", "Sat", "Sun"}
CJK_DATE = set("年月日号时点")          # year, month, day, hour, o'clock markers
DATE_WORDS = MONTHS | WEEKDAYS | CJK_DATE
# words after which a date or time is about to be written
LEAD_IN = {"born": -9.0, "on": -5.0, "dated": -6.0, "updated": -6.0, "until": -4.0,
           "from": -2.0, "at": -1.5}
READS = ()

def norm(s):
    """Token text with full-width digits and colon mapped to ASCII."""
    s = s.strip()
    if s == "：":
        return ":"
    if len(s) == 1 and unicodedata.decimal(s, None) is not None:
        return str(unicodedata.decimal(s))
    return s

def step(carry, prefix, upstream):
    raw = prefix.token_strings
    s = [norm(x) for x in raw]
    cur = s[-1]
    prev = s[-2] if len(s) > 1 else ""
    prev2 = s[-3] if len(s) > 2 else ""
    prev3 = s[-4] if len(s) > 3 else ""
    v = 0.0
    if cur.isdigit() and prev.isdigit() and prev2 == ":" and prev3.isdigit():
        # minutes digit of a clock time such as 9:0[0] am
        v = -9.0 if prev == "0" else -5.0
    elif cur in MONTHS:
        v = -12.0 if prev in WEEKDAYS else LEAD_IN.get(prev, -6.0 if prev == "," else -1.0)
    elif raw[-1] == " " and prev in WEEKDAYS:
        v = -9.0                      # space before a day number, e.g. Sat[ ]3
    elif raw[-1] == " " and prev == "," and prev2 == "Today":
        v = -6.0
    elif raw[-1] == " " and prev in LEAD_IN:
        v = LEAD_IN[prev]
    elif cur == "," and prev in WEEKDAYS:
        v = -5.0
    elif cur in WEEKDAYS:
        v = -1.0
    elif cur.isdigit() and any(x in DATE_WORDS for x in s[-8:-1]):
        v = -0.7                      # digits of a date written out in words or Chinese
    return carry, float(v)

