"""Approximate source-code boundary signals with a short recent-text buffer.

Control-header parentheses and loop initializers are negative. Grouped imports
and Go declarations are strongly positive; explicit method receivers and Go
return lists have smaller positive signals. Array-type suffixes, destructuring
braces, and continuations of conventionally prefixed type names are negative.
Merged parentheses have different strengths from standalone parentheses.
Escaped newlines are recognized, documents reset the buffer, and other tokens
are mostly zero. This is a collection of syntax cues, not a full code parser.
"""
import re

READS = ()
CONTROL = {'if', 'elif', 'for', 'foreach', 'while', 'switch', 'catch'}
DECLARATION_STARTS = {
    'int', 'long', 'short', 'float', 'double', 'char', 'bool',
    'unsigned', 'size_t', 'auto', 'var', 'let', 'const',
}
PRIMITIVE = re.compile(
    r'\b(?:u?int(?:8|16|32|64)?|UInt\d*|char|byte|short|long|float|double|'
    r'bool|string|String)\s*$'
)
LAST_WORD = re.compile(r'([A-Za-z_]+)\s*$')
METHOD = re.compile(r'\bdef\s+\w+\s*$')
RECEIVER = re.compile(r'\bdef\s+\w+\(\s*$')
HEADER = re.compile(r'\b(if|elif|for|foreach|while|switch|catch)\s*\(\s*$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ''
    else:
        tail = carry[1]
    token = prefix.token_strings[-1]
    s = token.strip()
    value = 0.0
    # Code is often quoted with literal backslash-newline escapes.
    context = tail.replace('\\n', '\n').replace('\\t', '\t')
    context = context.replace('\\r', '\r')
    last_word = LAST_WORD.search(context)
    word = last_word[1] if last_word else ''
    if s.startswith('(') and ')' not in s:
        if word in CONTROL:
            before = context[:last_word.start()].rstrip()
            prose = before and (before[-1].isalpha() or before[-1] == '>')
            if prose and not before.endswith(('else', 'return')):
                value = 0.0
            elif word in {'for', 'foreach'}:
                value = -3.7
            elif s == '(' and word in {'switch', 'while', 'catch'}:
                value = -3.6 if word == 'switch' else -2.6
            elif s == '(':
                value = -2.2
            elif s in {'(!', '($', '(_'}:
                value = -2.4
            else:
                value = -1.2
        elif word in {'import', 'const', 'var'}:
            if s.startswith(("('", '("')):
                value = 2.7
            elif re.search(r'\bfrom[^\n]*import\s*$', context):
                value = 5.8
            else:
                value = 9.2
        elif s == '(' and word == 'return':
            value = 0.45
        elif s == '(' and word == 'func':
            value = 1.4
        elif s == '(' and re.search(r'\bfunc\b[^\n]*\)\s*$', context):
            value = 2.0
        elif s == '(':
            value = 0.03
        elif s in {'(self', '(cls'} and METHOD.search(context):
            value = 1.35
        elif word == 'func':
            value = 0.55
        elif s == '($':
            value = 0.3
    else:
        header = HEADER.search(context)
        if header and s:
            if header[1] in {'for', 'foreach'}:
                value = -2.5 if s in DECLARATION_STARTS or s == ';' else -0.5
            elif header[1] == 'catch':
                value = -1.0
            else:
                value = -0.2
        elif s in {'self', 'cls'} and RECEIVER.search(context):
            value = 1.4
        elif s == 'self' and re.search(r'&(?:mut)?\s*$', context):
            value = 1.0
        elif re.fullmatch(r'(?:\[[, ]*\])+', s) and PRIMITIVE.search(context):
            value = -2.0
        elif s == '{' and word in {'const', 'let', 'var'}:
            # Do not confuse a C++ trailing const qualifier with a binding.
            before = context[:last_word.start()].rstrip()
            value = 0.0 if before.endswith(')') else -3.5
        elif s == '()' and word == 'function':
            value = -0.95
    # Camel-case type names with conventional I, T, U or E prefixes.
    if value == 0.0 and token.isalpha():
        pref = re.search(r'\b([ITUE])([A-Z]?)\Z', context)
        if pref:
            continuation = token.islower() if pref[2] else (
                token[0].isupper() and any(c.islower() for c in token)
            )
            if continuation:
                value = (-2.3 if pref[2] else -4.0) if pref[1] == 'I' else -1.4
    return (doc, (tail + token)[-100:]), value

