"""Opening parenthesis of a control-statement header (if, for, while, catch, switch, elif,
foreach, with, except): strongly negative. The first token inside a C-style for header
is also negative. Everything else is zero."""
READS = ()

CONTROL = {"if", "elif", "for", "foreach", "while", "catch", "switch", "except", "with"}


def step(carry, prefix, upstream):
    s = prefix.token_strings
    cur = s[-1].strip()
    prev = s[-2].strip() if len(s) > 1 else ""
    prev2 = s[-3].strip() if len(s) > 2 else ""
