"""Recognize doubled s, especially in short fragments and at token joins.

This includes possessive 's after s, German sharp/long s, Cyrillic s,
and Japanese small-tsu plus an s-row syllable. Surname endings -sson
and -ssen receive an extra boost. Ordinary long words
containing ss get only a small response. English corpus frequency and
capitalization distinguish familiar words from fragments/abbreviations.
An ss fragment after s is suppressed, as are short, familiar English
forms with two ss groups spanning a join.
The previous token and a split double-s ending reset at each document.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
S_ROW = frozenset('さしすせそサシスセソ')


@lru_cache(maxsize=8192)
def frequency(word):
    return zipf_frequency(word, 'en')


def spelling(text):
    return text.lower().replace('ſ', 's').replace('ß', 'ss')


def doubled_fragment(c, p):
    """An ss inside the newest token: short pieces respond most."""
    s = spelling(c).strip()
    n = len(s)
    j = s.find('ss')
    after = n - j - 2
    if c[:1].isalpha() and (q := spelling(p).strip()):
        if q.endswith('s') and s.startswith('ss'):
            return -1.0  # A run of three s letters, not a doubled s.
        if (n <= 6 and (q + s).count('ss') >= 2
                and frequency(q + s) > 3.0):
            return -2.0  # Familiar English words with two ss groups.
    if 'ß' in c and not c[:1].isspace():
        return 2.6
    if c.isupper() and n > 3:
        return 0.5
    if (n <= 6 and s.endswith('ssen')
            and (not c[:1].isspace() or s.endswith('assen'))):
        return 3.8
    if 3 <= n <= 5 and s.startswith('ss'):
        return 4.2
    if n <= 3:
        if s.startswith('s'):
            if c[:1].isspace():
                return 1.0
            return 1.9 if c[:1].isupper() else 3.2
        if j > 0 and s[j - 1] == 'i':
            return 2.9
        return 3.3 if after > 0 else 1.1
    f = frequency(s)
    if f > 3.25:
        return 0.25 if n <= 4 else 0.08
    if n <= 5:
        if j > 0 and s[j - 1] == 'i':
            return 3.6
        return 2.1 if after > 0 else 0.65
    return 0.45 if n == 6 else 0.08


def step(carry, prefix, upstream):
    c = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    p, split_double = ('', False)
    if carry is not None and carry[0] == doc:
        p, split_double = carry[1:]
    s, q = spelling(c), spelling(p)
    word, previous = s.strip(), q.strip()
    n, m = len(word), len(previous)
    double_end = (q[-1:] + s).endswith('ss') if s else False
    state = (doc, c, double_end)

    if c in ("'s", '’s'):
        if q.endswith('s'):
            value = 7.0 if m > 1 else 1.3
        elif q.endswith(('sh', 'ch', 'ce', 'se', 'x', 'z')):
            value = 1.4
        else:
            value = 0.2 if 's' in q else -0.04
    elif 'ss' in s:
        value = doubled_fragment(c, p)
    elif q.endswith('s') and s.startswith('s'):
        if c == 'ſ':
            value = 8.0
        elif c[:1].isupper():
            if m <= 2:
                value = 2.0
            else:
                value = 0.7 if c.isupper() else 0.0
        elif n > 4:
            value = 0.35
        elif word in ('son', 'sen'):
            value = 7.5  # Patronymic surname endings, e.g. -sson/-ssen.
        elif n >= 3 and frequency(word) > 4.7:
            value = 2.0
        else:
            value = 3.4 if frequency(previous) > 3.7 else 4.6
    elif (q.endswith('ss') or split_double) and c[:1].isalpha():
        if p == 'ſ':
            value = 4.8 if n <= 3 else 1.0
        elif n == 1:
            value = 2.0 if m > 3 else (
                6.2 if frequency(previous + word) > 2.8 else 3.6)
        elif m <= 4:
            value = 0.5
            if n <= 3:
                value = 1.0 if frequency(previous) > 4.8 else 3.0
        else:
            value = 0.3 if n <= 3 else 0.1
    elif (p.endswith(('っ', 'ッ')) and c[:1] in S_ROW
          or len(c) == 2 and c[0] in 'っッ' and c[1] in S_ROW):
        value = 3.2
    elif p.endswith('с') and c == 'с':
        value = 3.2
    elif 'сс' in c:
        value = 1.8 if len(c.strip()) <= 4 else 0.1
    else:
        value = 0.0
    return state, value

"""Approximate a mixed grammatical-word feature.

The rules respond most strongly to non-finite 'be', proximal demonstratives,
and first-person self-reference (especially 'let me'). Small named sets cover
related words in several languages. There are also code cases: 'self',
'return', and a member-access arrow after 'this'. Previous words, indentation
and document starts
adjust the amplitudes. Most small content-token fluctuations are not modeled.
