ROMANCE_THIS = {
    'ce', 'cet', 'cette', 'ces',
    'este', 'esta', 'estes', 'estas', 'esto', 'estos',
    'esse', 'essa', 'esses', 'essas',
    'questo', 'questa', 'questi', 'queste',
