    value = -0.006

    if w == 'be':
        value = 1.23 if word == 'be' else 0.46
        if word == 'be':
            if previous.lower() in {'can', 'cannot'}:
                value = 1.57
            elif previous.lower() == 'would':
                value = 0.92
            elif previous.lower() in {'will', 'might'}:
