        value = 1.12
    elif w == 'being':
        value = 0.66
    elif w in {'être', 'быть', 'essere'}:
        value = 1.1
    elif w == 'ser':
        value = 0.50
    elif w == 'été':
        value = 0.82
    elif w in {'this', 'these'}:
        value = 0.68
        if token[:1] in '.(\t':
            value = 0.36
    elif w in ROMANCE_THIS or w in GERMAN_THIS:
        value = 1.15 + (0.55 if split else 0.0)
    elif w == 'bu':
        value = 0.65
    elif w in RUSSIAN_THIS:
        value = 0.75
    elif w == 'me':
        value = 0.72
        if previous.lower() == 'let':
            value = 1.68 if previous == 'Let' else 1.47
        if word != 'me':
            value = 0.23
    elif w in {'my', 'myself', 'mine'}:
        value = 0.54 if word == w else 0.34
    elif w in FIRST_PERSON:
        value = 1.12
    elif w in {'mich', 'mir'}:
        value = 0.66
    elif w == 'tôi':
        value = 0.53
    elif word == 'I':
        value = 0.15 if token[:1].isspace() else 0.02
        if previous.lower() in {
            'if', 'when', 'because', 'that', 'perhaps', 'maybe'
        }:
            value = 0.43
    elif w == 'will' and previous in {'I', 'we', 'We'}:
        value = 0.92 if previous == 'I' else 0.5
    elif w == 'am':
        value = 0.55 if previous.lower() == 'i' else 0.15
    elif token in {"'m", '’m'}:
        value = 0.61
    elif token in {"'re", '’re'}:
        value = 0.40
    elif token in {"'ll", '’ll'}:
        value = 0.95 if previous == 'I' else 0.0
        if previous.lower() == 'we':
            value = 0.45
    elif token in {"'s", '’s'} and previous.lower() in {'let', 'here'}:
        value = 0.63
