"""layers.1.mlp.down_proj:2932: a "be / me / this" word detector.

What the component does: it writes one fixed direction into the residual stream, and how
strongly it does so depends almost only on the word being read. It is large on the verb
"be" and its forms ("be", "been", "being", and foreign equivalents such as "être"),
on "me" (strongest in "Let me"), on "this"/"these" and their foreign equivalents
("cet", "esta", "diese", "эта"), on the first-person "my"/"I'm"/"я", and on "return"
when it starts a line of code. Most other words are near zero.

The program looks the current word up in a small table of typical activations. It applies
two context rules, both read from the previous word: "be" right after a modal ("can be",
"must be") is stronger, and "return" after plain English words (not after indentation or
code punctuation) is zero. It keeps no state between positions.
"""

# Typical activation of each word, from training text.
BE_WORDS = {"be": 1.2, "been": 1.1, "being": 0.65, "être": 1.2, "быть": 0.9}
ME_WORDS = {"me": 0.9, "my": 0.5, "myself": 0.5, "'m": 0.6, "я": 0.6, "jag": 0.9, "могу": 0.9}
THIS_WORDS = {
    "this": 0.7, "these": 0.65, "cet": 1.4, "cette": 1.2, "ces": 0.6, "esta": 1.3,
    "este": 0.8, "diese": 1.2, "dieser": 1.2, "questo": 1.0, "эта": 1.1, "этой": 1.1,
}
OTHER_WORDS = {"self": 0.5, "return": 0.7}
VALUES = {**BE_WORDS, **ME_WORDS, **THIS_WORDS, **OTHER_WORDS}

# Modal verbs: a "be" right after one of these is stronger.
MODALS = {"can", "cannot", "could", "may", "might", "must", "should", "shall"}


def step(carry, prefix, upstream):
    # No state is carried between positions; the carry stays None.
    tokens = prefix.token_strings
    word = tokens[-1].strip().lower()
    prev = tokens[-2].strip().lower() if len(tokens) > 1 else ""
    value = VALUES.get(word, 0.0)
    if word == "be" and prev in MODALS:
        value = 1.5
    if word == "me" and prev == "let":
        value = 1.7
    if word == "return" and prev.isalpha():
        value = 0.0  # "return" after an English word is prose, not code
    return None, float(value)


