"""Detect Zhang/jang spellings, with a small document-opening response.

张/張 produce a strong negative value, especially as a sheet/card classifier
following a count or demonstrative. Longer tokens containing these characters
are weaker. Korean 장 and Romanized Zhang also produce negative values.
Split UTF-8 characters and split Roman spellings are joined incrementally.
The capitalized present-tense question auxiliaries Is/Are/Do/Does produce a
positive value at a document's first token. Other tokens predict zero.
"""

READS = ()
COUNT_DETERMINERS = frozenset(
    '一二三四五六七八九十百千万亿两几数每半这那哪整'
)
PRESENT_QUESTION_AUXILIARIES = frozenset({'Is', 'Are', 'Do', 'Does'})


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, b'', '')
    _, previous_bytes, previous_text = carry
    raw = prefix.token_bytes[-1]
    text = raw.decode('utf-8', 'ignore')
    if raw and 0x80 <= raw[0] < 0xC0:
        text = (previous_bytes + raw).decode('utf-8', 'ignore')
    word = text.strip()
    value = 0.0

    if '张' in word or '張' in word:
        character = '張' if '張' in word else '张'
        before, _, after = word.partition(character)
        if not after and all(ch in COUNT_DETERMINERS or ch.isdigit()
                             for ch in before):
            if before:
                value = -9.0 if character == '張' else -8.2
            else:
                value = -9.0 if character == '張' else -6.9
                # A numeral or demonstrative makes 张 a sheet/card classifier.
                left = previous_text.rstrip()[-1:]
                if left and (left in COUNT_DETERMINERS or left.isdigit()):
                    value = -10.0 if character == '張' else -9.5
        else:
            value = -1.7
    elif word == '장':
        value = -3.2
    elif 'zhang' in word.lower():
        value = -4.7
    elif text and (previous_text + text).lower().endswith('zhang'):
        value = -6.9
    elif raw == '张'.encode('utf-8')[:2]:
        # The shared, unfinished UTF-8 prefix of 张 and 張.
        value = -3.0
    elif first and text in PRESENT_QUESTION_AUXILIARIES:
        value = 2.0

    return (doc, (previous_bytes + raw)[-2:],
            (previous_text + text)[-8:]), value

"""A surface-language approximation of a multilingual pronoun response.

Recent word frequencies disambiguate es/il/het/det by language. English
it depends on its preceding interrogative or verb; word-internal it is
positive instead. Selected Chinese 它/其 forms are negative, and English
plural pronouns weakly positive. Other tokens default to zero. This
targets the high-CI pronoun pattern, not most background variation.
