import re
from functools import lru_cache
from wordfreq import zipf_frequency
from wordnet import base_forms

READS = ()
LANGUAGES = ('en', 'de', 'es', 'fr', 'it', 'nl', 'sv', 'nb', 'da')


@lru_cache(maxsize=8192)
def commonness(word, language):
    return max(0.0, zipf_frequency(word, language) - 3.0)


def language(words):
    if not words:
        return 'en'
    return max(LANGUAGES, key=lambda lang: sum(
        commonness(word, lang) for word in words))


def english_it(previous):
    if previous in {'what', 'whatever'}:
        return -0.98
    if previous in {'when', 'which', 'how'}:
        return -0.43
    if previous in {'where', 'whether', 'before', 'until'}:
        return -0.25
    bases = set(base_forms(previous)) | {previous}
    if previous == 'made' or 'have' in bases:
        return -0.78
    if bases & {'make', 'find', 'deem', 'leave', 'give', 'bring'}:
        return -0.58
    if bases & {'think', 'consider'}:
        return -0.43
    if bases & {'get', 'take', 'put', 'be', 'do'}:
        return -0.28
    if previous in {'and', 'but', 'because', 'although', 'though',
                    'if', 'to', 'with', 'about'}:
        return 0.0
    if previous == 'since' or bases & {'use', 'add'}:
        return 0.15
    return -0.15


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    value = 0.0
    if '它' in word and not word.startswith('其它'):
        value = -0.90 if any(ch in word for ch in '们們') else -1.45
        if word.startswith(('把', '将', '將', '让', '讓')):
            value -= 0.30
    elif word in {'将其', '將其'}:
        value = -1.70
    elif lower in {'they', 'them', 'their'}:
        value = 0.04 if lower == 'their' else 0.095
    elif (lower in {'it', 'its', 'es', 'il', 'het', 'det'}
          or word in {"'il", '’il', '-il', "'s", '’s', '其'}):
        words = re.findall(r'[^\W\d_]+', tail.lower())[-20:]
        previous = words[-1] if words else ''
        # Punctuation interrupts the immediately preceding grammatical cue.
        adjacent = previous if re.search(r'[^\W\d_]\s*$', tail) else ''
        boundary = token[:1].isspace() or not tail or not tail[-1:].isalpha()
        if lower == 'it':
            if word == 'IT':
                value = 0.10
            elif word == 'it' and not boundary:
                value = 0.22
            elif word == 'It' and adjacent == '':
                value = 0.03
            else:
                value = english_it(adjacent)
                if re.search(r"\bwhat[’']s\s*$", tail.lower()):
                    value = -0.98
                elif adjacent in {'is', 'was'} and len(words) > 1:
                    if words[-2] in {'what', 'whatever', 'how'}:
                        value = -0.70
        elif lower == 'its':
            value = 0.28 if adjacent in {'and', 'or'} else 0.04
        elif word in {"'il", '’il'}:
            value = -0.62
        elif word == '-il':
            value = -0.43
        elif word in {"'s", '’s'}:
            value = -0.90 if language(words) == 'de' else 0.02
        elif word == '其':
            value = -1.10 if tail.endswith(('将', '將', '使', '把')) else -0.43
        else:
            lang = language(words)
            if lower == 'es':
                value = -0.06 if word.islower() else -0.20
                if lang == 'de' and boundary:
                    value = -2.42 if token[:1].isspace() else -1.85
                    if adjacent in {'gibt', 'gab', 'gebe', 'geben', 'gäbe'}:
                        value = -1.36
            elif lower == 'il':
                value = -0.72 if lang == 'fr' and boundary else 0.02
            elif lower == 'het':
                value = -0.90 if lang == 'nl' and boundary else 0.0
            elif lower == 'det':
                value = -0.60 if lang in {'sv', 'nb', 'da'} and boundary else 0.0
    return (doc, (tail + token)[-240:]), value

"""Approximate this component with an onset pulse and weak syntax signals.

At a document's opening, words and comment/documentation openers give large
negative values; ordinary punctuation is weaker, and short indentation is
near zero. Script, case and spacing refine these rounded training estimates.
The pulse persists through a prefix made of one repeated token. Elsewhere,
small rules cover quoted fields, source-package paths, code terminators and
whitespace-prefixed "at". Detailed word-specific/context effects are omitted.
"""
import math
import regex

READS = ()


def opening_value(text):
    s = text.strip()
    if text.startswith('<|'):
        if s == '<|im_start|>':
            return -10.1
        return -7.3 if s == '<|im_end|>' else -5.5
    if not s:
        if '\n' in text:
            return -4.7 if text == '\n' else -3.2
        if set(text) == {' '}:
            return 0.15 if len(text) <= 3 else -1.8
        return -3.5
    if s.isdecimal():
        return -3.75
    indent_scale = 0.5 if text.startswith(' ') else 1.0
    if s.startswith('/*'):
        return indent_scale * (-19.5 if s.startswith('/**') else -16.2)
    if s in {'"""', "'''"}:
        return -19.5 * indent_scale
    if s == '**':  # Markdown emphasis opener
        return -18.2 * indent_scale
    if set(s) == {'#'} or (set(s) == {'/'} and len(s) >= 2):
        if text.endswith('\n'):
            return 3.6  # An empty comment/heading line, rather than its opener.
        pulse = -10.0 / math.sqrt(len(s)) if s[0] == '#' else -11.0
        return pulse * indent_scale
    if len(s) > 1 and set(s) == {'·'}:  # Middle-dot leader
        return -7.5
    if regex.search(r'\p{Script=Han}', s):
        return -4.65
    if regex.search(r'[\p{Script=Hiragana}\p{Script=Katakana}]', s):
        return -5.2
    if s.isalpha():
        if not s.isascii():
            return -5.6
        if len(s) == 1:
            return -5.35
        if text.startswith(' '):
            return -5.7
        return -7.0 if s[0].isupper() else -5.3
    if not any(c.isalnum() for c in s):
        if '\ufffd' in s:
            return -3.9
        if text.startswith(' '):
            return -2.1
        return -2.8 if s.isascii() else -3.0
    return -4.9


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening_value(prefix.token_strings[-1])
        carry = (doc, token, True, value)
    else:
        same = carry[2] and token == carry[1]
        carry = (doc, carry[1], same, carry[3])
        value = carry[3] if same else syntax_value(prefix)
    return carry, value


def syntax_value(prefix):
    """Weak lexical and syntax responses: at, quoted fields, paths, terminators."""
    text = prefix.token_strings[-1]
    s = text.strip()
    previous = prefix.token_strings[-2]
    if text.startswith(' ') and s.lower() == 'at':
        return -0.35
    if s == 'EOF':  # Shell here-document boundary
        recent = ''.join(prefix.token_strings[-6:])
        return 2.0 if '<<' in recent else 0.4
    if '`' in text and '\n' in text:
        return 0.3
    if s == '.com' and previous.rstrip().endswith('github'):
        return 3.0
    if s == '_modules' and previous.rstrip().endswith('node'):
        return 1.1
    if any(c in s for c in '\"\'“”'):
        if s.startswith('"') and any(c.isalpha() for c in s):
            recent = ''.join(prefix.token_strings[-16:])
            return 1.3 if 'import' in recent and '(' in recent else 0.2
        if ':' in s:
            return 0.8 if any(c in s for c in '\"“”') else 0.5
        if s.startswith(',') or ',' in s and any(c in s for c in '“”'):
            return 0.5
        if '\\' in s:
            return 0.4
        if s.endswith('\"') and (text.startswith(' ') or s[0] in '({='):
            return 0.2
    return 0.0

"""Approximate this component with short, local phrase templates.

Positive templates concern indefinite amounts and explanatory/topic complements.
A few type/manner idioms and recognizable code/log formats give negative values.
This deliberately leaves idiosyncratic identifier responses unexplained. It uses
only two adjacent tokens, never crossing a document boundary; otherwise it is zero.
"""
import inflect
import wordnet

READS = ()
CARDINALS = {inflect.engine().number_to_words(i) for i in range(1, 21)}

# Nouns introducing a description, aggregation, or topic, grouped by complement.
COMPLEMENTS = {
    'of': set('''
        analysis description discussion evidence examination explanation
        illustration implementation overview proof review snippet survey theorem
        understanding summary collection combination assortment sequence
        investigation account outline
    '''.split()),
    'on': set('''
        book detail discussion emphasis experiment information research thought
        variant comment note essay article literature instruction tutorial tip
    '''.split()),
    'for': set('method package technique tool evidence strategy'.split()),
    'to': set('approach attention guide introduction method solution function'.split()),
    'about': {'information'},
    'into': {'insight'},
}


def response(previous, token):
    p, w = previous.strip().lower(), token.strip().lower()
    # A separate space is usually the first token of a numerical amount.
    if token == ' ':
        if p == 'some':
            return 4.9
        if p == 'any':
            return 3.1
        if p in {'another', 'additional'}:
            return 1.6
        if p in {'estimated', 'further', 'minimum', 'initial', 'potential'}:
            return 0.8
        if p in {'all', 'every'}:
            return 0.5
    if token.startswith(' '):
        if w in CARDINALS or w == 'single':
            if p == 'any':
                return 4.3 if w == 'two' else 3.4 if w == 'one' else 1.7
            if p == 'no' and w in {'one', 'two'}:
                return 1.7 if w == 'one' else 4.3
            if p == 'some':
                return 6.0 if w == 'two' else 2.8
            if p == 'another':
                return 2.3 if w == 'one' else 1.4
            if p in {'other', 'or', 'following', 'which'}:
                return 0.7
        if p in {'some', 'any'} and w == 'sort':
            return -1.3
        if p == 'some' and w in {'form', 'reason'}:
            return -0.4 if w == 'form' else -2.0
        if p == 'any' and w == 'way':
            return -1.0
        if p == 'sort' and w == 'of':
            return -0.9
        if p in {'some', 'any', 'most'} and w == 'other':
            return 1.0 if p == 'some' else 0.4
        if p in {'some', 'more'} and w == 'context':
            return 0.8
        if p in {'something', 'anything'} and w == 'to':
            return 2.4
        if p == 'nothing' and w == 'to':
            return 0.9
        if p in {'more', 'something'} and w == 'like':
            return 1.2
        if p == 'more' and w in {'about', 'on'}:
            return 0.9
        if w in COMPLEMENTS:
            nouns = set(wordnet.base_forms(p, 'noun')) | {p}
            if nouns & COMPLEMENTS[w]:
                if w == 'of' and p == 'summary':
                    return 1.7
                return {'of': 0.65, 'on': 1.0, 'to': 0.3,
                        'for': 0.5, 'about': 0.6, 'into': 0.8}[w]
    # Standard test-log statuses, lint suppression, and Python special names.
    if p == '===' and token == ' RUN':
        return -2.5
    if p == '---' and w in {'pass', 'fail'}:
        return -1.8 if w == 'pass' else -3.5
    if p == 'npm' and w == 'err':
        return -2.3
    if p == '--' and token == 'git':
        return -1.4
    if p == 'noqa' and token == ':':
        return -4.0
    if p == 'name' and token.startswith('__'):
        return -1.8
    if p in {'eq', 'hash'} and token.startswith('__('):
        return -1.0
    if p in {'required', 'optional'} and w == 'parameter':
        return -2.2 if p == 'required' else -0.8
    # Repeated visible-space marks, as in rendered indentation.
    if previous == token == '··':
        return -0.63
    return 0.0


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    return None, response(prefix.token_strings[-2], prefix.token_strings[-1])

programs.haiku:
"""Layer 1's MLP hidden unit 2939, which carries about 70% of this component's variance
(the component is that unit's output, scaled). It is near zero on most tokens and large on a
few kinds of word.

What it responds to, in words a reader can check against the text:

- Strongly positive on the word right after an indefinite quantifier when that word is a
  count: a number or "one" / "two" ("some 120", "any two", "no two", "any one"). It is
  strongest after "some", then "any", "another", "no".
- Mildly positive on other words after a quantifier ("some great", "any big").
- Negative on the head noun after "some / any" when it is a kind or a reason that takes
  "of" ("some kind of", "any sort", "no way", "for some reason").
- Positive on "of" and "on" after nouns that name information or a collection, the things
  a text is about: "a summary of", "a collection of", "a snippet of", "comments on".
- Positive on "to" after "something", "anything", "nothing" ("something to eat").
- Strongly negative on the status words of test-runner logs: "=== RUN", "--- PASS", "--- FAIL".
- Strongly negative on the "-doc" of the generated comment marker "end-user-doc".

Everything else is close to zero. Scores one position at a time from the current token and
the one before it (within the same document).
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

COUNT_AFTER = {"some": 3.9, "any": 2.5, "another": 1.7, "no": 1.5}
COUNTS = {"one", "two", "three", "four", "five", "ten"}
OTHER_AFTER = {"some": 0.25, "any": 0.15, "something": 0.25, "anything": 0.2, "nothing": 0.15}
KIND_NOUNS = {"kind", "sort", "way", "form", "reason"}
INFO_NOUNS = {
    "summary", "collection", "snippet", "description", "overview", "review", "comments",
    "comment", "information", "research", "evidence", "examples", "example", "sample",
    "explanation", "discussion", "analysis", "study", "report", "details", "notes",
    "literature", "book", "books", "combination", "comparison", "breakdown", "outline",
    "survey", "account", "indication", "results",
}
TEST_MARKERS = {"===", "---"}
TEST_WORDS = {"RUN", "PASS", "FAIL"}


def step(carry, prefix, upstream: Mapping):
    cur = prefix.token_strings[-1].strip()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip() if same_doc else ""
    if prev in TEST_MARKERS and cur in TEST_WORDS:
        return carry, -2.0
    if prev == "end-user" and cur == "-doc":
        return carry, -6.0
    if prev in COUNT_AFTER and (cur in COUNTS or cur == "" or cur.isdigit()):
        return carry, COUNT_AFTER[prev]
    if prev in ("some", "any") and cur in KIND_NOUNS:
        return carry, -1.0
    if prev in OTHER_AFTER:
        return carry, OTHER_AFTER[prev]
    if prev in {"something", "anything", "nothing"} and cur == "to":
        return carry, 1.2
    if prev in INFO_NOUNS and cur in {"of", "on"}:
        return carry, 0.6
    return carry, 0.0

programs.sol:
"""A local spelling-fragment signal: hin/hill and split h+i are negative.

Positive rules cover im/ym continuations, zig, and -ig, especially im/ym
after z or zh. This models observed spellings, not word meanings. Case,
word boundaries and
whether h belongs to a digraph distinguish otherwise similar fragments.
The -illion number suffix also gets a positive value. Coefficients are
approximate training averages; longer-context differences are not modelled.
An otherwise unmarked document-start token gets a small negative baseline.
"""
import regex as re
from functools import lru_cache
from anyascii import anyascii

READS = ()

@lru_cache(maxsize=32768)
def spelling(text):
    return anyascii(text).lower()


def spelling_signal(text, previous):
    s = spelling(text).strip().strip("'")
    p = spelling(previous).rstrip().rstrip("'")
    spaced = bool(text[:1].isspace())
    capital = bool(text.strip()[:1].isupper())
    # Whole hi-fragments here are Latin spellings, not transliterations
    # of complete syllables in unrelated writing systems.
    latin = bool(re.fullmatch(r'\p{Script=Latin}+', text.strip()))
    if latin:
        if s == 'hin':
            return -10.4 if spaced and not capital else -5.45
        if s == 'hinh':
            return -4.67
        if s == 'hill':
            return -4.34 if capital else (-3.1 if spaced else -5.98)
        if s == 'hil':
            return -1.35 if capital else -3.61
        if s in ('hills', 'hind', 'him', 'hym', 'hick'):
            if s == 'him' and spaced and not capital:
                return -0.16
            return -1.55
        if s == 'zig':
            return 0.81 if spaced else 3.32
        if s == 'illion' and not spaced:
            return 2.95 if p.endswith('t') else 0.46
    if re.search(r'\p{Script=Hangul}', text + previous):
        return 0.002
    if not spaced and re.fullmatch(r'[iy][a-z]{0,4}', s):
        # h and zh have opposite signs.  sh/ch/ph/th are not a bare h.
        if p.endswith('zh'):
            return 6.43 if s in ('im', 'ym') else 0.33
        if p.endswith('h'):
            if p.endswith(('sh', 'ch', 'ph', 'th', 'kh', 'wh')):
                if p.endswith(('sh', 'th')) and s in ('in', 'il', 'ill', 'ills'):
                    return -2.7
                return 0.002
            if s in ('in', 'ins'):
                return -8.84
            if s in ('ill', 'imm', 'ina', 'ine', 'inz'):
                return -6.91
            if s in ('il', 'im', 'ym'):
                return -3.78
            if s.startswith(('in', 'il')) and len(s) <= 4:
                return -1.97
            return -0.19
        if s in ('im', 'ym'):
            if p.endswith(('z', 'j')):
                return 3.02
            if p.endswith('d') and s == 'ym':
                return 3.16
            if p[-1:].isalpha():
                return 0.36
        if s == 'ig' and p[-1:].isalpha():
            return 0.2
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    previous = '' if new_document else carry[1]
    text = prefix.token_strings[-1]
    value = spelling_signal(text, previous)
    if new_document and value == 0.002:
        value = -0.13
    return (doc, text), value

programs.haiku:
"""Layer-1 MLP down-projection feature 2943 of Qwen3-1.7B, as a readable rule set.

What it responds to, in plain terms. The feature is quiet almost everywhere. Its large
values come from the wording of short labels, not from the topic of the text:

* Strongly positive on "by" in a photo or byline credit: "Photo by", "Website by",
  "design by", "Photo and video by", "Guest Post by", "Posts by" (largest for photo
  credits). "Courtesy of" is also positive.
* Strongly negative on the bare space between "Question" (or "Article", "Claim") and its
  number: "Question 1", "## Question 3", "Test Question 1".
* Weakly positive on the bare space before a day or figure number after a month name or
  a "Figure", "Rule" or "Case" label ("March 15", "Figure 2").
* Weakly negative on "only".
* Positive at the start of a document when its first token is an indentation tab or a
  carriage return, as in code. Other document-initial tokens are idiosyncratic and are
  predicted as 0.

Magnitudes are halved from the typical peak sizes: these rules fire in few contexts and
are often wrong in size, so shrinking them toward 0 scored better on held-out rows.
Everywhere else it predicts 0.
"""

READS = ()

PHOTO_CREDIT = {"Photo", "photo", "Website", "website", "design", "Design", "video", "Video"}
BYLINE = {"Post", "Posts", "Posted", "posted", "Editing", "Published", "Summary", "Search",
          "Created", "created", "Modified", "modified", "Written", "written", "Sort"}
NUMBERED = {"Question", "Article", "Claim"}
DATE_OR_LABEL = {"January", "February", "March", "April", "May", "June", "July", "August",
                 "September", "October", "November", "December", "Figure", "Rule", "Case"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    first = len(prefix) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]
    if first:
        return carry, (0.75 if cur[:1] in ("\t", "\r") else 0.0)
    prev = prefix.token_strings[-2].strip()
    word = cur.strip()
    value = 0.0
    if word == "by" and prev in PHOTO_CREDIT:
        value = 1.25
    elif word == "by" and prev in BYLINE:
        value = 0.4
    elif word == "of" and prev in {"courtesy", "Courtesy"}:
        value = 0.75
    elif cur == " " and prev in NUMBERED:
        value = -1.25
    elif cur == " " and prev in DATE_OR_LABEL:
        value = 0.1
    elif word == "only":
        value = -0.1
    return carry, float(value)
